// ЗГЕНЕРОВАНО `deno task core:sql` з server/sql/**/db/*.sql — не редагувати.
//
// Текст SQL ядра, вбудований у модуль. Причина, чому не text-імпорти
// (`with { type: "text" }`) — у tools/generate-core-sql.ts: їх не розбирає
// граф JSR, і публікація server-пакета падає.

export const CORE_SQL_TEXT: Record<string, string> = {
  "access/db/access.sql": "-- Функції підсистеми доступу.\n--\n-- Дві групи:\n--   1. app.access_* — перевірка права. Це те, на що спирається і рантайм, і\n--      застосунок; ім'я моделі збігається з тим, що приходить у\n--      ModelRuntimeService.execute(model, command, ...).\n--   2. app.user_* / app.user_group_* — звичайний модельний контракт\n--      (list / get / save / delete / lookup), щоб застосунок міг зробити\n--      будь-які екрани керування доступом, не вигадуючи запитів.\n--\n-- Паролів тут немає: хеш рахує TS (PBKDF2-SHA256). app.user_save створює\n-- користувача з порожнім хешем — увійти під ним не можна, доки пароль не\n-- встановлять через auth-модуль. Так схема хешування лишається в одному місці.\n\n-- ── Службове ───────────────────────────────────────────────────────────────\n\n/** Порожня частина `data` конверта — щоб відповіді-помилки мали ту саму форму. */\ndrop function if exists app.access_empty_data();\ncreate function app.access_empty_data()\nreturns jsonb\nlanguage sql\nimmutable\nas $$\n  select jsonb_build_object(\n    'item', null,\n    'rows', '[]'::jsonb,\n    'options', '{}'::jsonb,\n    'totals', '{}'::jsonb\n  );\n$$;\n\n-- ── Перевірка права ────────────────────────────────────────────────────────\n\n/**\n * Чи дозволена дія над моделлю цьому користувачеві.\n * Право дає будь-яка активна група, у якій він складається; запис із model='*'\n * діє на всі моделі. Відсутність запису — заборона.\n */\ndrop function if exists app.access_can(bigint, text, text);\ncreate function app.access_can(p_user_id bigint, p_model text, p_action text)\nreturns boolean\nlanguage sql\nstable\nas $$\n  select exists (\n    select 1\n    from app.user_group_member m\n    join app.user_group g on g.id = m.user_group_id and g.is_active\n    join app.user_group_permission p on p.user_group_id = g.id\n    where m.user_id = p_user_id\n      and m.is_active\n      and p.is_allowed\n      and p.action = p_action\n      and (p.model = '*' or p.model = p_model)\n  );\n$$;\n\n/**\n * Відмова у праві — у тому самому конверті, що й будь-яка інша відповідь.\n *\n * Живе в SQL, бо саме звідси й повертається: рантайм не питає право окремим\n * запитом, а вкладає перевірку в той самий `select`, що викликає команду\n * (`case when access_can(...) then <команда>(...) else access_denied(...) end`).\n * Один round-trip, і команда при відмові навіть не виконується — CASE не\n * обчислює невибрану гілку.\n */\ndrop function if exists app.access_denied(text, text);\ncreate function app.access_denied(p_model text, p_action text)\nreturns jsonb\nlanguage sql\nimmutable\nas $$\n  select jsonb_build_object(\n    'ok', false,\n    'data', app.access_empty_data(),\n    'messages', jsonb_build_array(\n      format('Немає права «%s» на модель «%s»', p_action, p_model)\n    )\n  );\n$$;\n\n/**\n * Відмова через тимчасовий пароль — або NULL, якщо міняти нічого не треба.\n *\n * NULL, а не boolean, свідомо: рантайм загортає виклик команди в\n * `coalesce(password_change_denied(uid), <команда>)`, а coalesce не обчислює\n * наступні аргументи, коли перший не NULL. Один round-trip, і команда при\n * заблокованому паролі не виконується взагалі — так само, як із access_denied.\n */\ndrop function if exists app.password_change_denied(bigint);\ncreate function app.password_change_denied(p_user_id bigint)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  select case when u.must_change_password then jsonb_build_object(\n      'ok', false,\n      'data', app.access_empty_data(),\n      'messages', jsonb_build_array('Потрібно змінити тимчасовий пароль')\n    ) end\n  from app.users u\n  where u.id = p_user_id;\n$$;\n\n/**\n * Ефективні права користувача — плоский список (model, action).\n * Застосунку зручно отримати його один раз і вимикати кнопки локально,\n * не питаючи сервер на кожен елемент.\n */\ndrop function if exists app.access_effective(bigint, jsonb);\ncreate function app.access_effective(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with target as (\n    select coalesce(nullif(payload->>'userId', '')::bigint, user_id) as uid\n  ),\n  granted as (\n    select distinct p.model, p.action\n    from app.user_group_member m\n    join app.user_group g on g.id = m.user_group_id and g.is_active\n    join app.user_group_permission p on p.user_group_id = g.id\n    cross join target t\n    where m.user_id = t.uid\n      and m.is_active\n      and p.is_allowed\n    order by p.model, p.action\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(jsonb_build_object('model', model, 'action', action)) from granted), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', jsonb_build_object('count', (select count(*) from granted))\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\n-- ── Користувачі ────────────────────────────────────────────────────────────\n\ndrop function if exists app.user_list(bigint, jsonb);\ncreate function app.user_list(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '')                              as search,\n      greatest(coalesce((payload->>'page')::int, 1), 1)             as page,\n      least(greatest(coalesce((payload->>'pageSize')::int, 20), 1), 200) as page_size,\n      coalesce(nullif(payload->>'sortBy', ''), 'login')             as sort_by,\n      case lower(coalesce(payload->>'sortDir', 'asc')) when 'desc' then 'desc' else 'asc' end as sort_dir\n  ),\n  filtered as (\n    select\n      u.id::text                                     as id,\n      u.login                                        as login,\n      u.full_name                                    as \"fullName\",\n      u.is_active                                    as \"isActive\",\n      count(m.id) filter (where m.is_active)::int    as \"groupCount\"\n    from app.users u\n    left join app.user_group_member m on m.user_id = u.id\n    cross join params p\n    where p.search = ''\n       or u.login ilike '%' || p.search || '%'\n       or u.full_name ilike '%' || p.search || '%'\n    group by u.id, u.login, u.full_name, u.is_active\n  ),\n  paged as (\n    select f.*\n    from filtered f\n    cross join params p\n    order by\n      case when p.sort_by = 'login'     and p.sort_dir = 'asc'  then f.login end asc,\n      case when p.sort_by = 'login'     and p.sort_dir = 'desc' then f.login end desc,\n      case when p.sort_by = 'fullName'  and p.sort_dir = 'asc'  then f.\"fullName\" end asc,\n      case when p.sort_by = 'fullName'  and p.sort_dir = 'desc' then f.\"fullName\" end desc,\n      case when p.sort_by = 'isActive'  and p.sort_dir = 'asc'  then f.\"isActive\" end asc,\n      case when p.sort_by = 'isActive'  and p.sort_dir = 'desc' then f.\"isActive\" end desc,\n      f.login asc\n    limit (select page_size from params)\n    offset ((select page from params) - 1) * (select page_size from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(paged)) from paged), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', jsonb_build_object(\n        'count', (select count(*) from filtered),\n        'page', (select page from params),\n        'pageSize', (select page_size from params)\n      )\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\ndrop function if exists app.user_get(bigint, jsonb);\ncreate function app.user_get(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with target as (\n    select nullif(payload->>'id', '')::bigint as id\n  ),\n  found as (\n    select u.* from app.users u cross join target t where u.id = t.id\n  ),\n  member_groups as (\n    select g.id::text as id, g.code, g.name, m.is_active as \"isActive\"\n    from app.user_group_member m\n    join app.user_group g on g.id = m.user_group_id\n    cross join target t\n    where m.user_id = t.id\n    order by g.code\n  ),\n  all_groups as (\n    select g.id::text as id, g.name from app.user_group g where g.is_active order by g.code\n  ),\n  identities as (\n    select\n      i.id::text        as id,\n      i.provider        as provider,\n      i.external_id     as \"externalId\",\n      i.email           as email,\n      i.display_name    as \"displayName\",\n      i.last_login_at   as \"lastLoginAt\"\n    from app.user_identity i\n    cross join target t\n    where i.user_id = t.id\n    order by i.provider, i.external_id\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', (\n        select jsonb_build_object(\n          'id', f.id::text,\n          'login', f.login,\n          'fullName', f.full_name,\n          'isActive', f.is_active,\n          'groupIds', coalesce((select jsonb_agg(id) from member_groups where \"isActive\"), '[]'::jsonb),\n          -- Зв'язки із зовнішніми провайдерами. Повний стан, а не дельта:\n          -- user_save переписує список цілком, як і членство в групах.\n          'identities', coalesce((select jsonb_agg(row_to_json(identities)) from identities), '[]'::jsonb)\n        )\n        from found f\n      ),\n      'rows', coalesce((select jsonb_agg(row_to_json(member_groups)) from member_groups), '[]'::jsonb),\n      'options', jsonb_build_object(\n        'groups', coalesce((select jsonb_agg(row_to_json(all_groups)) from all_groups), '[]'::jsonb)\n      ),\n      'totals', '{}'::jsonb\n    ),\n    'messages', case when exists (select 1 from found)\n      then '[]'::jsonb\n      else jsonb_build_array('Користувача не знайдено') end\n  );\n$$;\n\n/**\n * Створення/зміна користувача.\n * payload = { item: { id, login, fullName, isActive, groupIds, identities } }.\n *\n * Пароль не приймається: новий користувач створюється з порожнім хешем і не\n * може увійти, доки пароль не встановлять через auth-модуль.\n *\n * `identities` — зв'язки із зовнішніми провайдерами входу. Поле\n * **необов'язкове**, і його відсутність означає «не чіпати»: інакше будь-яка\n * форма, що про зв'язки не знає, мовчки відв'язувала б людину від провайдера\n * при звичайному збереженні імені.\n */\ndrop function if exists app.user_save(bigint, jsonb);\ncreate function app.user_save(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\n-- Параметр контракту зветься user_id і збігається з іменем колонки\n-- app.user_group_member.user_id — в ON CONFLICT це неоднозначність. Вирішуємо\n-- на користь колонки, а сам параметр далі беремо через v_actor.\n#variable_conflict use_column\ndeclare\n  v_actor  bigint := user_id;\n  v_item   jsonb := coalesce(payload->'item', '{}'::jsonb);\n  v_id     bigint := nullif(v_item->>'id', '')::bigint;\n  v_login  text := trim(coalesce(v_item->>'login', ''));\n  v_name   text := trim(coalesce(v_item->>'fullName', ''));\n  v_active boolean := coalesce((v_item->>'isActive')::boolean, true);\n  v_groups bigint[] := coalesce(\n    (select array_agg(value::bigint) from jsonb_array_elements_text(coalesce(v_item->'groupIds', '[]'::jsonb))),\n    '{}'::bigint[]\n  );\n  v_identities jsonb := v_item->'identities';\n  v_taken text;\nbegin\n  if v_login = '' then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Логін обов''язковий'));\n  end if;\n\n  if v_name = '' then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Повне ім''я обов''язкове'));\n  end if;\n\n  if exists (select 1 from app.users u where lower(u.login) = lower(v_login) and (v_id is null or u.id <> v_id)) then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Логін уже зайнятий'));\n  end if;\n\n  if v_id is null then\n    insert into app.users (login, password_hash, full_name, is_active)\n    values (v_login, '', v_name, v_active)\n    returning id into v_id;\n  else\n    update app.users\n       set login = v_login, full_name = v_name, is_active = v_active, updated_at = now()\n     where id = v_id;\n\n    if not found then\n      return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Користувача не знайдено'));\n    end if;\n  end if;\n\n  -- Членство переписуємо цілком: список груп у формі — повний стан, а не дельта.\n  delete from app.user_group_member m where m.user_id = v_id and not (m.user_group_id = any(v_groups));\n\n  insert into app.user_group_member (user_group_id, user_id, is_active)\n  select g, v_id, true from unnest(v_groups) as g\n  on conflict (user_group_id, user_id) do update set is_active = true, updated_at = now();\n\n  if jsonb_typeof(v_identities) = 'array' then\n    if exists (\n      select 1 from jsonb_array_elements(v_identities) e\n      where trim(coalesce(e->>'provider', '')) = '' or trim(coalesce(e->>'externalId', '')) = ''\n    ) then\n      return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages',\n        jsonb_build_array('Для зв''язки потрібні провайдер і зовнішній ідентифікатор'));\n    end if;\n\n    if exists (\n      select 1 from jsonb_array_elements(v_identities) e\n      group by lower(trim(e->>'provider')), trim(e->>'externalId')\n      having count(*) > 1\n    ) then\n      return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages',\n        jsonb_build_array('Однакова зв''язка вказана двічі'));\n    end if;\n\n    -- Зайнято іншим користувачем. Перевіряємо явно, хоча є унікальний індекс:\n    -- інакше замість зрозумілого тексту прилетів би 500 від порушення\n    -- обмеження, а адміністратор не дізнався б, що саме не так.\n    select string_agg(distinct u.login, ', ')\n      into v_taken\n    from jsonb_array_elements(v_identities) e\n    join app.user_identity i\n      on i.provider = lower(trim(e->>'provider'))\n     and i.external_id = trim(e->>'externalId')\n    join app.users u on u.id = i.user_id\n    where i.user_id <> v_id;\n\n    if v_taken is not null then\n      return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages',\n        jsonb_build_array('Цю зв''язку вже використовує: ' || v_taken));\n    end if;\n\n    -- Список у формі — повний стан, як і членство в групах.\n    delete from app.user_identity i\n     where i.user_id = v_id\n       and not exists (\n         select 1 from jsonb_array_elements(v_identities) e\n         where lower(trim(e->>'provider')) = i.provider\n           and trim(e->>'externalId') = i.external_id\n       );\n\n    insert into app.user_identity (user_id, provider, external_id, email, display_name)\n    select\n      v_id,\n      lower(trim(e->>'provider')),\n      trim(e->>'externalId'),\n      nullif(trim(coalesce(e->>'email', '')), ''),\n      nullif(trim(coalesce(e->>'displayName', '')), '')\n    from jsonb_array_elements(v_identities) e\n    on conflict (provider, external_id) do update\n       set email = excluded.email,\n           display_name = excluded.display_name,\n           updated_at = now()\n     where app.user_identity.user_id = v_id;\n  end if;\n\n  return app.user_get(v_actor, jsonb_build_object('id', v_id::text));\nend;\n$$;\n\ndrop function if exists app.user_delete(bigint, jsonb);\ncreate function app.user_delete(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_id bigint := nullif(payload->>'id', '')::bigint;\nbegin\n  if v_id is null then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('id обов''язковий'));\n  end if;\n\n  if v_id = user_id then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Не можна видалити самого себе'));\n  end if;\n\n  -- На користувача посилаються документи й вкладення (created_by та інші),\n  -- тому видалення можливе лише коли слідів немає. Інакше — деактивація.\n    if exists (select 1 from app.document d where v_id in (d.created_by, d.updated_by, d.posted_by))\n      or exists (select 1 from app.attachment a where a.created_by = v_id)\n      or exists (select 1 from app.audit_log l where l.user_id = v_id) then\n    update app.users set is_active = false, updated_at = now() where id = v_id;\n    return jsonb_build_object(\n      'ok', true,\n      'data', app.access_empty_data(),\n      -- modal: true — операція пройшла, але не так, як чекав користувач, і\n      -- банер у списку тут не годиться: рядок уже зник з екрана.\n      'messages', jsonb_build_array(jsonb_build_object(\n        'type', 'info',\n        'modal', true,\n        'text', 'Користувач має пов''язані документи — його деактивовано, а не видалено'\n      ))\n    );\n  end if;\n\n  delete from app.users where id = v_id;\n  return jsonb_build_object('ok', true, 'data', app.access_empty_data(), 'messages', '[]'::jsonb);\nend;\n$$;\n\ndrop function if exists app.user_lookup(bigint, jsonb);\ncreate function app.user_lookup(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '') as search,\n      least(coalesce((payload->>'limit')::int, 50), 200) as lim\n  ),\n  rows as (\n    select u.id::text as id, coalesce(nullif(trim(u.full_name), ''), u.login) as name\n    from app.users u\n    cross join params p\n    where u.is_active\n      and (p.search = '' or u.login ilike '%' || p.search || '%' or u.full_name ilike '%' || p.search || '%')\n    order by u.login\n    limit (select lim from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(rows)) from rows), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\n-- ── Групи користувачів ─────────────────────────────────────────────────────\n\ndrop function if exists app.user_group_list(bigint, jsonb);\ncreate function app.user_group_list(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '') as search,\n      greatest(coalesce((payload->>'page')::int, 1), 1) as page,\n      least(greatest(coalesce((payload->>'pageSize')::int, 20), 1), 200) as page_size,\n      coalesce(nullif(payload->>'sortBy', ''), 'code') as sort_by,\n      case lower(coalesce(payload->>'sortDir', 'asc')) when 'desc' then 'desc' else 'asc' end as sort_dir\n  ),\n  filtered as (\n    select\n      g.id::text as id,\n      g.code,\n      g.name,\n      g.is_active as \"isActive\",\n      count(distinct m.user_id) filter (where m.is_active)::int as \"memberCount\",\n      count(distinct p.id) filter (where p.is_allowed)::int      as \"permissionCount\"\n    from app.user_group g\n    left join app.user_group_member m on m.user_group_id = g.id\n    left join app.user_group_permission p on p.user_group_id = g.id\n    cross join params prm\n    where prm.search = '' or g.code ilike '%' || prm.search || '%' or g.name ilike '%' || prm.search || '%'\n    group by g.id, g.code, g.name, g.is_active\n  ),\n  paged as (\n    select f.* from filtered f cross join params p\n    order by\n      case when p.sort_by = 'code' and p.sort_dir = 'asc'  then f.code end asc,\n      case when p.sort_by = 'code' and p.sort_dir = 'desc' then f.code end desc,\n      case when p.sort_by = 'name' and p.sort_dir = 'asc'  then f.name end asc,\n      case when p.sort_by = 'name' and p.sort_dir = 'desc' then f.name end desc,\n      f.code asc\n    limit (select page_size from params)\n    offset ((select page from params) - 1) * (select page_size from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(paged)) from paged), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', jsonb_build_object(\n        'count', (select count(*) from filtered),\n        'page', (select page from params),\n        'pageSize', (select page_size from params)\n      )\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\ndrop function if exists app.user_group_get(bigint, jsonb);\ncreate function app.user_group_get(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with target as (\n    select nullif(payload->>'id', '')::bigint as id\n  ),\n  found as (\n    select g.* from app.user_group g cross join target t where g.id = t.id\n  ),\n  permissions as (\n    select p.id::text as id, p.model, p.action, p.is_allowed as \"isAllowed\"\n    from app.user_group_permission p\n    cross join target t\n    where p.user_group_id = t.id\n    order by p.model, p.action\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', (\n        select jsonb_build_object(\n          'id', f.id::text,\n          'code', f.code,\n          'name', f.name,\n          'isActive', f.is_active\n        )\n        from found f\n      ),\n      'rows', coalesce((select jsonb_agg(row_to_json(permissions)) from permissions), '[]'::jsonb),\n      'options', jsonb_build_object(\n        'actions', jsonb_build_array(\n          jsonb_build_object('id', 'view',   'name', 'Перегляд'),\n          jsonb_build_object('id', 'create', 'name', 'Введення нового'),\n          jsonb_build_object('id', 'edit',   'name', 'Редагування'),\n          jsonb_build_object('id', 'delete', 'name', 'Видалення'),\n          jsonb_build_object('id', 'post',   'name', 'Проведення'),\n          jsonb_build_object('id', 'unpost', 'name', 'Скасування проведення')\n        )\n      ),\n      'totals', '{}'::jsonb\n    ),\n    'messages', case when exists (select 1 from found)\n      then '[]'::jsonb\n      else jsonb_build_array('Групу не знайдено') end\n  );\n$$;\n\n/**\n * Створення/зміна групи разом із правами.\n * payload = { item: { id, code, name, isActive }, rows: [ { model, action, isAllowed } ] }\n * rows — повний стан прав групи, а не дельта.\n */\ndrop function if exists app.user_group_save(bigint, jsonb);\ncreate function app.user_group_save(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_item   jsonb := coalesce(payload->'item', '{}'::jsonb);\n  v_rows   jsonb := coalesce(payload->'rows', '[]'::jsonb);\n  v_id     bigint := nullif(v_item->>'id', '')::bigint;\n  v_code   text := trim(coalesce(v_item->>'code', ''));\n  v_name   text := trim(coalesce(v_item->>'name', ''));\n  v_active boolean := coalesce((v_item->>'isActive')::boolean, true);\nbegin\n  if v_code = '' then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Код групи обов''язковий'));\n  end if;\n\n  if v_name = '' then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Назва групи обов''язкова'));\n  end if;\n\n  if exists (select 1 from app.user_group g where lower(g.code) = lower(v_code) and (v_id is null or g.id <> v_id)) then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Група з таким кодом уже є'));\n  end if;\n\n  if v_id is null then\n    insert into app.user_group (code, name, is_active) values (v_code, v_name, v_active) returning id into v_id;\n  else\n    update app.user_group set code = v_code, name = v_name, is_active = v_active, updated_at = now() where id = v_id;\n    if not found then\n      return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Групу не знайдено'));\n    end if;\n  end if;\n\n  delete from app.user_group_permission where user_group_id = v_id;\n\n  insert into app.user_group_permission (user_group_id, model, action, is_allowed)\n  select\n    v_id,\n    trim(r->>'model'),\n    trim(r->>'action'),\n    coalesce((r->>'isAllowed')::boolean, true)\n  from jsonb_array_elements(v_rows) as r\n  where coalesce(trim(r->>'model'), '') <> '' and coalesce(trim(r->>'action'), '') <> ''\n  on conflict (user_group_id, model, action) do update\n    set is_allowed = excluded.is_allowed, updated_at = now();\n\n  return app.user_group_get(user_id, jsonb_build_object('id', v_id::text));\nend;\n$$;\n\ndrop function if exists app.user_group_delete(bigint, jsonb);\ncreate function app.user_group_delete(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_id bigint := nullif(payload->>'id', '')::bigint;\nbegin\n  if v_id is null then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('id обов''язковий'));\n  end if;\n\n  delete from app.user_group where id = v_id;\n  if not found then\n    return jsonb_build_object('ok', false, 'data', app.access_empty_data(), 'messages', jsonb_build_array('Групу не знайдено'));\n  end if;\n\n  return jsonb_build_object('ok', true, 'data', app.access_empty_data(), 'messages', '[]'::jsonb);\nend;\n$$;\n\ndrop function if exists app.user_group_lookup(bigint, jsonb);\ncreate function app.user_group_lookup(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '') as search,\n      least(coalesce((payload->>'limit')::int, 50), 200) as lim\n  ),\n  rows as (\n    select g.id::text as id, g.name\n    from app.user_group g\n    cross join params p\n    where g.is_active\n      and (p.search = '' or g.code ilike '%' || p.search || '%' or g.name ilike '%' || p.search || '%')\n    order by g.code\n    limit (select lim from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(rows)) from rows), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n",
  "access/db/data.sql": "-- Початкові дані підсистеми доступу.\n--\n-- Дві групи «з коробки»: повний доступ і лише перегляд. Обидві описані через\n-- model='*', тому не залежать від складу моделей конкретного застосунку.\n-- Застосунок може їх перейменувати, доповнити або видалити — це лише старт.\n\ninsert into app.user_group (code, name, is_active) values\n  ('admin',  'Повний доступ', true),\n  ('viewer', 'Тільки перегляд', true)\non conflict (code) do update\n  set name = excluded.name, updated_at = now();\n\n-- Повний доступ: усі дії над усіма моделями.\ninsert into app.user_group_permission (user_group_id, model, action, is_allowed)\nselect g.id, '*', a.action, true\nfrom app.user_group g\ncross join (values ('view'), ('create'), ('edit'), ('delete'), ('post'), ('unpost')) as a(action)\nwhere g.code = 'admin'\non conflict (user_group_id, model, action) do update\n  set is_allowed = true, updated_at = now();\n\n-- Тільки перегляд.\ninsert into app.user_group_permission (user_group_id, model, action, is_allowed)\nselect g.id, '*', 'view', true\nfrom app.user_group g\nwhere g.code = 'viewer'\non conflict (user_group_id, model, action) do update\n  set is_allowed = true, updated_at = now();\n\n-- Якщо в системі є рівно один користувач і він поза групами — це той, кого\n-- створив bootstrap. Без цього першого входу після переїзду на права не буде.\ninsert into app.user_group_member (user_group_id, user_id, is_active)\nselect g.id, u.id, true\nfrom app.user_group g\ncross join (select id from app.users order by id limit 1) u\nwhere g.code = 'admin'\n  and (select count(*) from app.users) = 1\n  and not exists (select 1 from app.user_group_member m where m.user_id = u.id)\non conflict (user_group_id, user_id) do nothing;\n",
  "access/db/migration.sql": "-- Синхронізація лічильників identity.\n--\n-- Рядки могли потрапити в таблиці з явними id — перенесенням зі старої схеми\n-- або seed-даними. Тоді лічильник лишається на початку, і перший же insert без\n-- id падає з \"duplicate key value violates unique constraint\". Виявляється це\n-- не при публікації, а при створенні першого справжнього користувача.\ndo $$\ndeclare\n  v_table text;\nbegin\n  foreach v_table in array array['users', 'user_group', 'user_group_member', 'user_group_permission', 'user_identity']\n  loop\n    execute format(\n      'select setval(pg_get_serial_sequence(%L, %L), coalesce((select max(id) from app.%I), 0) + 1, false)',\n      'app.' || v_table, 'id', v_table\n    );\n  end loop;\nend $$;\n\n-- Разові state redirect-потоку живуть хвилини. Основне прибирання робить TS при\n-- кожному новому вході; це — на випадок, коли потік довго не запускали взагалі.\ndelete from app.auth_login_state where expires_at < now();\n\n-- Прибирання legacy-груп епохи «доступу через інтерфейси» переїхало в struc.sql\n-- під маркер to_regclass('app.user_group_permission'): migration.sql виконується\n-- при КОЖНІЙ публікації, і без маркера чистка зносила б щойно створену\n-- адміністратором групу, яку ще не встигли наповнити правами.\n\ndo $$\nbegin\n\tif to_regclass('public.users') is not null then\n\t\tinsert into app.users (\n\t\t\tid,\n\t\t\tlogin,\n\t\t\tpassword_hash,\n\t\t\tfull_name,\n\t\t\tis_active,\n\t\t\tcreated_at,\n\t\t\tupdated_at\n\t\t)\n\t\tselect\n\t\t\tu.id,\n\t\t\tu.login,\n\t\t\tu.password_hash,\n\t\t\tu.full_name,\n\t\t\tu.is_active,\n\t\t\tu.created_at,\n\t\t\tu.updated_at\n\t\tfrom public.users u\n\t\ton conflict (id) do update\n\t\tset\n\t\t\tlogin = excluded.login,\n\t\t\tpassword_hash = excluded.password_hash,\n\t\t\tfull_name = excluded.full_name,\n\t\t\tis_active = excluded.is_active,\n\t\t\tcreated_at = excluded.created_at,\n\t\t\tupdated_at = excluded.updated_at;\n\n\t\tperform setval(\n\t\t\tpg_get_serial_sequence('app.users', 'id'),\n\t\t\tgreatest(coalesce((select max(id) from app.users), 1), 1),\n\t\t\ttrue\n\t\t);\n\tend if;\n\n\tif to_regclass('public.auth_session') is not null then\n\t\tinsert into app.auth_session (\n\t\t\tid,\n\t\t\tuser_id,\n\t\t\tauth_method,\n\t\t\ttoken_hash,\n\t\t\texpires_at,\n\t\t\tlast_seen_at,\n\t\t\trevoked_at,\n\t\t\tcreated_at,\n\t\t\tupdated_at\n\t\t)\n\t\tselect\n\t\t\ts.id,\n\t\t\ts.user_id,\n\t\t\ts.auth_method,\n\t\t\ts.token_hash,\n\t\t\ts.expires_at,\n\t\t\ts.last_seen_at,\n\t\t\ts.revoked_at,\n\t\t\ts.created_at,\n\t\t\ts.updated_at\n\t\tfrom public.auth_session s\n\t\twhere exists (\n\t\t\tselect 1\n\t\t\tfrom app.users u\n\t\t\twhere u.id = s.user_id\n\t\t)\n\t\ton conflict (id) do update\n\t\tset\n\t\t\tuser_id = excluded.user_id,\n\t\t\tauth_method = excluded.auth_method,\n\t\t\ttoken_hash = excluded.token_hash,\n\t\t\texpires_at = excluded.expires_at,\n\t\t\tlast_seen_at = excluded.last_seen_at,\n\t\t\trevoked_at = excluded.revoked_at,\n\t\t\tcreated_at = excluded.created_at,\n\t\t\tupdated_at = excluded.updated_at;\n\tend if;\nend\n$$;\n\n-- Прапорець тимчасового пароля (див. struc.sql). Для вже наявних користувачів\n-- false: їхні паролі задавала людина, а не оточення.\nalter table app.users\n  add column if not exists must_change_password boolean not null default false;\n",
  "access/db/struc.sql": "-- Підсистема доступу: користувачі, сесії, групи, права.\n--\n-- Живе у фреймворку, бо без неї не працює жоден застосунок: на app.users\n-- посилаються app.document (created_by/updated_by/posted_by) і app.attachment\n-- (created_by), а app.auth_session — основа авторизації.\n--\n-- Право описується трійкою «група → модель → дія». Модель — це ім'я з\n-- manifest.json, тобто те саме, що приходить у ModelRuntimeService.execute():\n-- завдяки цьому перевірка права лягає рівно на точку виконання команди.\n--\n-- Інтерфейсної частини тут немає навмисно. Фреймворк дає структури й функції;\n-- екрани керування користувачами застосунок робить як і де йому зручно.\n\ncreate extension if not exists pgcrypto;\ncreate schema if not exists app;\n\n-- Прив'язку доступу до «інтерфейсів» (наборів екранів) знято: право тепер\n-- описується дією над моделлю, а не набором меню. Таблиці лишалися від\n-- попереднього прототипу — їх не створював жоден чинний скрипт.\ndrop table if exists app.user_group_interface cascade;\ndrop table if exists app.user_interface cascade;\n\ncreate table if not exists app.users (\n  id            bigint generated by default as identity primary key,\n  login         varchar(100) not null unique,\n  -- Хеш рахує TS (PBKDF2-SHA256, див. server/modules/auth/password-hash.ts).\n  -- SQL паролів не торкається свідомо: одна схема хешування, одне місце.\n  password_hash varchar(255) not null,\n  full_name     varchar(255) not null,\n  is_active     boolean not null default true,\n  -- Пароль тимчасовий і мусить бути змінений при вході. Ставиться, коли\n  -- користувача створив bootstrap із BOOTSTRAP_PASSWORD: цей пароль лежить\n  -- відкритим текстом у .env і відомий усім, хто бачив файл. Прапорець тут, а\n  -- не в сесії, бо він переживає і вихід, і перезапуск сервера.\n  must_change_password boolean not null default false,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\ncreate index if not exists ix_users_is_active on app.users (is_active);\n\ncreate table if not exists app.auth_session (\n  id           uuid primary key default gen_random_uuid(),\n  user_id      bigint not null references app.users (id) on delete cascade,\n  auth_method  varchar(50) not null,\n  token_hash   varchar(64) not null unique,\n  expires_at   timestamptz not null,\n  last_seen_at timestamptz,\n  revoked_at   timestamptz,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index if not exists ix_auth_session_user_id on app.auth_session (user_id);\ncreate index if not exists ix_auth_session_active_lookup on app.auth_session (token_hash, expires_at)\n  where revoked_at is null;\n\n-- Зв'язка користувача із зовнішнім провайдером входу.\n--\n-- Ключ — стабільний ідентифікатор у провайдера (OIDC `sub`), а не e-mail:\n-- e-mail міняють, і зв'язка тихо переїхала б на іншу людину. Без рядка тут\n-- зовнішній вхід не пускає нікого — навіть якщо провайдер підтвердив особу.\n-- Виняток один: порожня база, коли зовнішнім входом заводиться перший\n-- адміністратор (див. AuthIdentityService).\ncreate table if not exists app.user_identity (\n  id          bigint generated by default as identity primary key,\n  user_id     bigint not null references app.users (id) on delete cascade,\n  -- Ключ методу входу (`AuthMethod.key`), не назва компанії.\n  provider    varchar(50) not null,\n  external_id varchar(255) not null,\n  -- Що провайдер сказав про особу на момент зв'язки. Довідково: жодне рішення\n  -- на цих полях не будується, звіряння йде тільки по external_id.\n  email       varchar(255),\n  display_name varchar(255),\n  last_login_at timestamptz,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\n\n-- Одна зовнішня особа — не більше ніж один користувач.\ncreate unique index if not exists uq_user_identity on app.user_identity (provider, external_id);\ncreate index if not exists ix_user_identity_user on app.user_identity (user_id);\n\n-- Разовий `state` redirect-потоку: захист від CSRF на callback.\n--\n-- У БД, а не в пам'яті процесу: `dev:server` ходить із --watch, і стан у пам'яті\n-- помирав би при кожному перезапуску рівно посеред відлагодження редиректу.\n-- Значення зберігається як є — за RFC 6749 `state` не секрет, а разовий nonce;\n-- сам собою він нічого не відкриває, бо без `code` від провайдера сесії не буде.\ncreate table if not exists app.auth_login_state (\n  state       varchar(64) primary key,\n  auth_method varchar(50) not null,\n  -- Куди повернути користувача в інтерфейсі. Тільки шлях від кореня —\n  -- абсолютний URL тут став би відкритим редиректом (перевіряє TS).\n  redirect_to varchar(500),\n  expires_at  timestamptz not null,\n  -- Погашено: другий callback із тим самим state нічого не дасть.\n  consumed_at timestamptz,\n  created_at  timestamptz not null default now()\n);\n\ncreate index if not exists ix_auth_login_state_expires on app.auth_login_state (expires_at);\n\ncreate table if not exists app.user_group (\n  id         bigint generated by default as identity primary key,\n  code       varchar(50) not null unique,\n  name       varchar(255) not null,\n  is_active  boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate index if not exists ix_user_group_is_active on app.user_group (is_active);\n\ncreate table if not exists app.user_group_member (\n  id            bigint generated by default as identity primary key,\n  user_group_id bigint not null references app.user_group (id) on delete cascade,\n  user_id       bigint not null references app.users (id) on delete cascade,\n  is_active     boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\n-- Унікальність потрібна не лише для чистоти: на неї спирається ON CONFLICT\n-- в AuthService.ensureDefaultAccess().\ncreate unique index if not exists uq_user_group_member on app.user_group_member (user_group_id, user_id);\ncreate index if not exists ix_user_group_member_user on app.user_group_member (user_id) where is_active;\n\n-- ── Одноразове прибирання прототипу ────────────────────────────────────────\n-- Групи епохи «доступу через інтерфейси» були лише контейнерами наборів\n-- екранів і власних прав не мали — у новій схемі вони не значать нічого.\n-- Маркер — таблиця НОВОЇ схеми (як у server/sql/menu): app.user_group_permission\n-- не існує рівно до першої публікації цього файлу, тому умова істинна\n-- один-єдиний раз, і прав у жодної групи на той момент ще немає. Перевіряти\n-- «групу без прав» у migration.sql не можна: він виконується при кожній\n-- публікації і зносив би щойно створену групу, яку ще не наповнили правами.\ndo $$\nbegin\n  if to_regclass('app.user_group_permission') is null then\n    delete from app.user_group\n    where code not in ('admin', 'viewer');\n  end if;\nend $$;\n\n-- Дії. Перші чотири мають сенс для будь-якої моделі, останні дві — лише для\n-- документів (тип моделі оголошений у manifest.json, а не в БД, тому обмежити\n-- їх на рівні таблиці не можна — це перевіряє рантайм).\n--   view   — перегляд: list, get, lookup\n--   create — введення нового запису\n--   edit   — зміна наявного\n--   delete — видалення\n--   post   — проведення документа\n--   unpost — скасування проведення\ncreate table if not exists app.user_group_permission (\n  id            bigint generated by default as identity primary key,\n  user_group_id bigint not null references app.user_group (id) on delete cascade,\n  -- Ім'я моделі з manifest.json або '*' — «усі моделі».\n  model         varchar(100) not null,\n  action        varchar(20) not null,\n  is_allowed    boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  constraint ck_user_group_permission_action\n    check (action in ('view', 'create', 'edit', 'delete', 'post', 'unpost')),\n  constraint ck_user_group_permission_model\n    check (model = '*' or model ~ '^[a-z][a-z0-9_]*$')\n);\n\ncreate unique index if not exists uq_user_group_permission\n  on app.user_group_permission (user_group_id, model, action);\ncreate index if not exists ix_user_group_permission_group\n  on app.user_group_permission (user_group_id) where is_allowed;\n",
  "attachment/db/attachment.sql": "-- Ядро підсистеми вкладень.\n--\n-- Дві групи функцій, і вони навмисно різні:\n--\n-- 1. Бінарні (attachment_load / attachment_update) — приймають і повертають\n--    звичайні колонки, зокрема bytea. Контракт `(user_id, payload jsonb) →\n--    jsonb` тут не діє свідомо: байти в jsonb довелося б возити base64 (+33%\n--    трафіку й зайве кодування на кожен бік). Їх кличе не ModelRuntimeService,\n--    а server/modules/blob.\n--\n-- 2. Модельні (attachment_list / get / save / delete) — звичайний контракт\n--    моделі, їх кличе ModelRuntimeService як команди моделі `attachment`.\n--    Байтів не торкаються: тільки метадані та прив'язка до власника.\n--\n-- Поле `token` у відповідях модельних функцій містить access_key (uuid).\n-- Підписаний токен доступу підставляє рантайм — див. server/modules/blob.\n\n-- ── 1. Бінарні функції ──────────────────────────────────────────────────────\n\n-- Читання вкладення разом із потоком даних. Аналог процедури `.Load`.\ndrop function if exists app.attachment_load(bigint, bigint);\ncreate function app.attachment_load(user_id bigint, attachment_id bigint)\nreturns table (\n  id         bigint,\n  name       varchar(255),\n  mime       varchar(255),\n  size       bigint,\n  sha256     varchar(64),\n  access_key uuid,\n  stream     bytea\n)\nlanguage sql\nas $$\n  select a.id, a.name, a.mime, a.size, a.sha256, a.access_key, a.stream\n  from app.attachment a\n  where a.id = attachment_id;\n$$;\n\n-- Запис нового вкладення. Аналог процедури `.Update`: повертає id та ключ\n-- доступу, з яких клієнт складає посилання і кладе id у свою модель.\n-- Власник (p_owner_model/p_owner_id) необов'язковий: форма нового запису ще\n-- не має id, тому спершу створюється «сирота», а прив'язку робить\n-- attachment_save після збереження самої моделі.\ndrop function if exists app.attachment_update(bigint, varchar, varchar, bytea, varchar, bigint, varchar);\ncreate function app.attachment_update(\n  p_user_id     bigint,\n  p_name        varchar(255),\n  p_mime        varchar(255),\n  p_stream      bytea,\n  p_owner_model varchar(80) default null,\n  p_owner_id    bigint      default null,\n  p_sha256      varchar(64) default null\n)\nreturns table (id bigint, access_key uuid)\nlanguage sql\nas $$\n  insert into app.attachment as a (name, mime, size, sha256, stream, owner_model, owner_id, created_by)\n  values (\n    nullif(trim(coalesce(p_name, '')), ''),\n    coalesce(nullif(trim(coalesce(p_mime, '')), ''), 'application/octet-stream'),\n    coalesce(length(p_stream), 0),\n    p_sha256,\n    p_stream,\n    nullif(trim(coalesce(p_owner_model, '')), ''),\n    p_owner_id,\n    p_user_id\n  )\n  returning a.id, a.access_key;\n$$;\n\n-- Прибирання «сиріт»: завантажили файл, але форму не зберегли.\n-- Викликається планово (cron/адмін-командою), не рантаймом.\ndrop function if exists app.attachment_gc(int);\ncreate function app.attachment_gc(p_older_than_hours int default 24)\nreturns bigint\nlanguage sql\nas $$\n  with removed as (\n    delete from app.attachment\n    where owner_model is null\n      and created_at < now() - make_interval(hours => greatest(p_older_than_hours, 1))\n    returning 1\n  )\n  select count(*)::bigint from removed;\n$$;\n\n-- ── 2. Модельні функції (команди моделі `attachment`) ───────────────────────\n\n-- Список вкладень запису: payload = { ownerModel, ownerId }.\ndrop function if exists app.attachment_list(bigint, jsonb);\ncreate function app.attachment_list(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nas $$\n  with src as (\n    select a.*\n    from app.attachment a\n    where a.owner_model = nullif(trim(coalesce(payload->>'ownerModel', '')), '')\n      and a.owner_id    = nullif(payload->>'ownerId', '')::bigint\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'rows', coalesce((\n        select jsonb_agg(jsonb_build_object(\n          'id',        s.id::text,\n          'name',      s.name,\n          'mime',      s.mime,\n          'size',      s.size,\n          'createdAt', s.created_at,\n          -- access_key; підписаний токен підставить рантайм\n          'token',     s.access_key\n        ) order by s.id)\n        from src s\n      ), '[]'::jsonb),\n      'item',    null,\n      'options', '{}'::jsonb,\n      'totals',  jsonb_build_object('count', (select count(*)::int from src)),\n      'extra',   '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb,\n    'meta', '{}'::jsonb\n  );\n$$;\n\n-- Одне вкладення (метадані + токен): payload = { id }.\ndrop function if exists app.attachment_get(bigint, jsonb);\ncreate function app.attachment_get(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nas $$\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', (\n        select jsonb_build_object(\n          'id',        a.id::text,\n          'name',      a.name,\n          'mime',      a.mime,\n          'size',      a.size,\n          'createdAt', a.created_at,\n          'token',     a.access_key\n        )\n        from app.attachment a\n        where a.id = nullif(payload->>'id', '')::bigint\n      ),\n      'rows',    '[]'::jsonb,\n      'options', '{}'::jsonb,\n      'totals',  '{}'::jsonb,\n      'extra',   '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb,\n    'meta', '{}'::jsonb\n  );\n$$;\n\n-- Прив'язка вкладення до власника і перейменування:\n-- payload = { item: { id, ownerModel?, ownerId?, name? } }.\n-- Саме цим форма «усиновлює» файли, завантажені до першого збереження запису.\ndrop function if exists app.attachment_save(bigint, jsonb);\ncreate function app.attachment_save(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_item jsonb := coalesce(payload->'item', '{}'::jsonb);\n  v_id   bigint := nullif(v_item->>'id', '')::bigint;\n  v_row  jsonb;\nbegin\n  if v_id is null then\n    raise exception 'attachment_save: id обов''язковий (байти завантажуються через /api/blob/upload)';\n  end if;\n\n  update app.attachment a\n  set owner_model = coalesce(nullif(trim(coalesce(v_item->>'ownerModel', '')), ''), a.owner_model),\n      owner_id    = coalesce(nullif(v_item->>'ownerId', '')::bigint, a.owner_id),\n      name        = coalesce(nullif(trim(coalesce(v_item->>'name', '')), ''), a.name)\n  where a.id = v_id\n  returning jsonb_build_object(\n    'id',        a.id::text,\n    'name',      a.name,\n    'mime',      a.mime,\n    'size',      a.size,\n    'createdAt', a.created_at,\n    'token',     a.access_key\n  ) into v_row;\n\n  if v_row is null then\n    raise exception 'attachment_save: вкладення % не знайдено', v_id;\n  end if;\n\n  return jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item',    v_row,\n      'rows',    '[]'::jsonb,\n      'options', '{}'::jsonb,\n      'totals',  '{}'::jsonb,\n      'extra',   '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb,\n    'meta', '{}'::jsonb\n  );\nend;\n$$;\n\n-- Видалення вкладення: payload = { id }.\ndrop function if exists app.attachment_delete(bigint, jsonb);\ncreate function app.attachment_delete(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_id bigint := nullif(payload->>'id', '')::bigint;\nbegin\n  delete from app.attachment where id = v_id;\n\n  return jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item',    null,\n      'rows',    '[]'::jsonb,\n      'options', '{}'::jsonb,\n      'totals',  '{}'::jsonb,\n      'extra',   jsonb_build_object('id', v_id::text)\n    ),\n    'messages', '[]'::jsonb,\n    'meta', '{}'::jsonb\n  );\nend;\n$$;\n",
  "attachment/db/struc.sql": "-- Вкладення (бінарний об'єкт): зображення, прикріплений файл тощо.\n-- Одна таблиця на весь застосунок: вкладення бувають і в документів, і в\n-- довідників, тому власник описується парою (owner_model, owner_id), а не\n-- окремою таблицею на кожну модель.\n--\n-- Зовнішнє сховище не використовується — байти лежать у bytea. Поле\n-- blob_name (ім'я набору в зовнішньому сховищі) свідомо відсутнє: якщо колись\n-- знадобиться S3/Azure, воно додається міграцією, а attachment_load починає\n-- повертати його замість stream.\ncreate table if not exists app.attachment (\n  id          bigint generated by default as identity primary key,\n  -- Ключ доступу. Сам по собі не є токеном: рантайм (server/modules/blob)\n  -- підписує ним токен разом із сесією та користувачем. Ротація ключа\n  -- (update … set access_key = gen_random_uuid()) миттєво знецінює всі\n  -- раніше видані токени цього вкладення.\n  access_key  uuid         not null default gen_random_uuid(),\n  name        varchar(255) not null,\n  mime        varchar(255) not null default 'application/octet-stream',\n  size        bigint       not null default 0,\n  sha256      varchar(64),\n  stream      bytea,\n  -- Власник вкладення: ключ моделі (invoice, counterparty…) та id запису.\n  -- Порожній власник — «сирота»: файл завантажили, але форму не зберегли.\n  -- Такі рядки прибирає app.attachment_gc.\n  owner_model varchar(80),\n  owner_id    bigint,\n  created_by  bigint references app.users(id),\n  created_at  timestamptz  not null default now()\n);\n\ncreate index if not exists ix_attachment_owner  on app.attachment (owner_model, owner_id);\ncreate index if not exists ix_attachment_sha256 on app.attachment (sha256);\ncreate index if not exists ix_attachment_orphan on app.attachment (created_at)\n  where owner_model is null;\n",
  "audit/db/struc.sql": "-- Незмінний журнал виконання команд моделей. Payload навмисно не зберігається:\n-- у ньому можуть бути паролі, токени або інші персональні дані; для аудиту\n-- достатньо виконавця, операції, запису та її результату.\ncreate table if not exists app.audit_log (\n  id          bigint generated by default as identity primary key,\n  occurred_at timestamptz not null default now(),\n  user_id     bigint not null references app.users (id) on delete restrict,\n  model       varchar(100) not null,\n  command     varchar(100) not null,\n  record_id   bigint,\n  is_success  boolean not null,\n  constraint ck_audit_log_model check (model ~ '^[a-z][a-z0-9_]*$'),\n  constraint ck_audit_log_command check (command ~ '^[a-zA-Z][a-zA-Z0-9_]*$')\n);\n\ncreate index if not exists ix_audit_log_record\n  on app.audit_log (model, record_id, occurred_at desc) where record_id is not null;\ncreate index if not exists ix_audit_log_user_time\n  on app.audit_log (user_id, occurred_at desc);",
  "base/db/base.sql": "-- Base SQL init does not publish model-local SQL functions.\n",
  "base/db/data.sql": "-- Base SQL init does not publish seed data.\n",
  "base/db/migration.sql": "-- Міграцій рівня фундаменту немає: перенесення public.users/auth_session у\n-- схему app переїхало разом із самими таблицями у @core/access.\n",
  "base/db/struc.sql": "-- Фундамент: розширення й схема. Більше тут нічого немає навмисно —\n-- користувачі, сесії, групи й права переїхали у власний пакет @core/access,\n-- бо це вже підсистема з власним контрактом, а не «база».\ncreate extension if not exists pgcrypto;\ncreate schema if not exists app;\n",
  "document_core/db/data.sql": "-- Види аналітики (субконто), доступні проводкам.\n-- Тут лише ті довідники, що реально є в репозиторії; новий вимір додається\n-- рядком нижче одночасно з появою моделі.\n--\n-- app.document_type НЕ наповнюється тут: типи документів генеруються з\n-- manifest.json моделей-документів у _generated/document-types.data.sql.\n\ninsert into app.analytic_dimension (\n  code, name, entity_kind, model_key, target_table, id_column, code_column, name_column, is_active\n)\nvalues\n  -- Організації тут немає свідомо: вона реквізит шапки документа, а не субконто.\n  ('counterparty', 'Контрагент', 'catalog', 'counterparty', 'app.counterparty', 'id', 'code', 'name', true),\n  ('bank',         'Банк',       'catalog', 'bank',         'app.bank',         'id', 'code', 'name', true)\non conflict (code) do update\nset\n  name         = excluded.name,\n  entity_kind  = excluded.entity_kind,\n  model_key    = excluded.model_key,\n  target_table = excluded.target_table,\n  id_column    = excluded.id_column,\n  code_column  = excluded.code_column,\n  name_column  = excluded.name_column,\n  is_active    = excluded.is_active;\n\n-- Які субконто веде рахунок. Тільки конкретні рахунки: на групи проводок\n-- не буває, тому рядок для групи був би обманом.\n-- Решта рахунків отримає аналітику разом із появою відповідних довідників.\n\ninsert into app.chart_of_account_analytic (account_code, slot_no, dimension_code, is_required)\nvalues\n  ('311', 1, 'bank',         true),\n  ('312', 1, 'bank',         true),\n  ('313', 1, 'bank',         true),\n  ('314', 1, 'bank',         true),\n  ('333', 1, 'counterparty', true),\n  ('361', 1, 'counterparty', true),\n  ('362', 1, 'counterparty', true),\n  ('371', 1, 'counterparty', true),\n  ('377', 1, 'counterparty', true),\n  ('631', 1, 'counterparty', true),\n  ('632', 1, 'counterparty', true),\n  ('681', 1, 'counterparty', true),\n  ('685', 1, 'counterparty', true)\non conflict (account_code, slot_no) do update\nset\n  dimension_code = excluded.dimension_code,\n  is_required    = excluded.is_required;\n",
  "document_core/db/document_core.sql": "-- ═══════════════════════════════════════════════════════════════════════════\n-- Процедури ядра документообігу.\n--\n-- Ними користуються команди post/unpost конкретних документів. Сама логіка\n-- проводок лишається у видимому SQL документа (app.<model>_post_entries) —\n-- декларативних правил проведення тут свідомо немає: у бухгалтерії дорожче\n-- «магія», ніж кілька рядків явного коду.\n--\n-- Типовий post документа:\n--   perform app.doc_post_begin(user_id, doc_id);\n--   perform app.doc_entry_add(doc_id, 1, '361', '701', 1200.00, null, 'Реалізація',\n--                             jsonb_build_object('counterparty', cp_id), '{}'::jsonb);\n--   perform app.doc_post_finish(user_id, doc_id);\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── Автонумерація ───────────────────────────────────────────────────────────\n-- Номер = префікс організації + префікс типу + порядковий номер у межах пари\n-- (тип, організація). Унікальність гарантує uq_document_number.\n\ndrop function if exists app.doc_next_number(varchar, bigint);\ncreate function app.doc_next_number(\n  p_type_code       varchar,\n  p_organization_id bigint\n) returns varchar\nlanguage plpgsql\nas $$\ndeclare\n  v_prefix text;\n  v_next   bigint;\nbegin\n  select coalesce(o.prefix, '') || coalesce(dt.prefix, '')\n    into v_prefix\n  from app.document_type dt\n  cross join app.organization o\n  where dt.code = p_type_code\n    and o.id = p_organization_id;\n\n  if v_prefix is null then\n    raise exception 'Невідомий тип документа «%» або організація %', p_type_code, p_organization_id;\n  end if;\n\n  select coalesce(max(nullif(substring(d.number from '[0-9]+$'), '')::bigint), 0) + 1\n    into v_next\n  from app.document d\n  join app.document_type dt on dt.id = d.document_type_id\n  where dt.code = p_type_code\n    and d.organization_id = p_organization_id;\n\n  return v_prefix || lpad(v_next::text, 6, '0');\nend;\n$$;\n\n-- ── Аналітика проводки ──────────────────────────────────────────────────────\n-- Розкладає значення субконто по слотах, які веде рахунок, і знімає з\n-- довідника знімок коду та назви. Зайві ключі ігноруються, відсутнє\n-- обов'язкове субконто — помилка.\n--\n-- p_values приймає обидві форми запису значення:\n--   {\"counterparty\": \"42\"}                       — лише id;\n--   {\"counterparty\": {\"id\": \"42\", \"name\": \"…\"}}  — id разом із представленням.\n-- Друга зручна документам: форма показує назву субконто після перезавантаження,\n-- не роблячи окремого запиту. Знімок для регістру ядро все одно бере з\n-- довідника, а не з документа, — щоб рух не залежав від того, що там лежало.\n\ndrop function if exists app.doc_analytic_set(bigint, varchar, varchar, jsonb);\ncreate function app.doc_analytic_set(\n  p_entry_id bigint,\n  p_side     varchar,\n  p_account  varchar,\n  p_values   jsonb\n) returns void\nlanguage plpgsql\nas $$\ndeclare\n  cfg    record;\n  v_raw  jsonb;\n  v_id   bigint;\n  v_code varchar(100);\n  v_name varchar(500);\nbegin\n  for cfg in\n    select\n      a.slot_no,\n      a.dimension_code,\n      a.is_required,\n      d.name as dimension_name,\n      d.target_table,\n      d.id_column,\n      d.code_column,\n      d.name_column\n    from app.chart_of_account_analytic a\n    join app.analytic_dimension d on d.code = a.dimension_code\n    where a.account_code = p_account\n    order by a.slot_no\n  loop\n    v_raw := coalesce(p_values, '{}'::jsonb) -> cfg.dimension_code;\n    v_id := case\n      when v_raw is null or jsonb_typeof(v_raw) = 'null' then null\n      when jsonb_typeof(v_raw) = 'object' then nullif(v_raw ->> 'id', '')::bigint\n      else nullif(v_raw #>> '{}', '')::bigint\n    end;\n\n    if v_id is null then\n      if cfg.is_required then\n        raise exception 'Не заповнено субконто «%» рахунку % (%)',\n          cfg.dimension_name, p_account, p_side;\n      end if;\n      continue;\n    end if;\n\n    begin\n      execute format(\n        'select %s::varchar, %s::varchar from %s where %I = $1',\n        coalesce(quote_ident(cfg.code_column), 'null'),\n        coalesce(quote_ident(cfg.name_column), 'null'),\n        cfg.target_table,\n        cfg.id_column\n      )\n      into strict v_code, v_name\n      using v_id;\n    exception when no_data_found then\n      raise exception 'Субконто «%»: запис % не знайдено в %',\n        cfg.dimension_name, v_id, cfg.target_table;\n    end;\n\n    insert into app.journal_entry_analytic (\n      journal_entry_id, side, slot_no, dimension_code,\n      value_id, value_code, value_name, value_presentation\n    )\n    values (\n      p_entry_id, p_side, cfg.slot_no, cfg.dimension_code,\n      v_id, v_code, v_name, coalesce(v_name, v_code, v_id::text)\n    )\n    on conflict (journal_entry_id, side, slot_no) do update\n    set\n      dimension_code     = excluded.dimension_code,\n      value_id           = excluded.value_id,\n      value_code         = excluded.value_code,\n      value_name         = excluded.value_name,\n      value_presentation = excluded.value_presentation;\n  end loop;\nend;\n$$;\n\n-- ── Початок проведення ──────────────────────────────────────────────────────\n-- Перевіряє документ і зносить попередні рухи: перепроведення завжди\n-- переписує регістр начисто, часткового оновлення проводок не буває.\n\ndrop function if exists app.doc_post_begin(bigint, bigint);\ncreate function app.doc_post_begin(\n  p_user_id     bigint,\n  p_document_id bigint\n) returns void\nlanguage plpgsql\nas $$\ndeclare\n  v_doc record;\nbegin\n  select id, is_deleted into v_doc\n  from app.document\n  where id = p_document_id;\n\n  if not found then\n    raise exception 'Документ % не знайдено', p_document_id;\n  end if;\n\n  if v_doc.is_deleted then\n    raise exception 'Документ % позначено на видалення — проведення неможливе', p_document_id;\n  end if;\n\n  delete from app.journal_entry where document_id = p_document_id;\nend;\n$$;\n\n-- ── Додати проводку ─────────────────────────────────────────────────────────\n\n-- Валюта й кількість — необов'язкові виміри проводки, що вмикаються ознаками\n-- рахунку (is_currency / is_quantitative), як і субконто. Правило те саме, що\n-- для субконто: якщо бодай один бік кореспонденції веде вимір, він обов'язковий;\n-- де не веде — ядро обнуляє, щоб у регістр не потрапляв «валютний» мотлох.\ndrop function if exists app.doc_entry_add(bigint, int, varchar, varchar, numeric, numeric, text, jsonb, jsonb);\ndrop function if exists app.doc_entry_add(bigint, int, varchar, varchar, numeric, numeric, text, jsonb, jsonb, bigint, numeric);\ncreate function app.doc_entry_add(\n  p_document_id      bigint,\n  p_line_no          int,\n  p_debit_account    varchar,\n  p_credit_account   varchar,\n  p_amount           numeric,\n  p_quantity         numeric default null,\n  p_description      text    default null,\n  p_debit_analytics  jsonb   default '{}'::jsonb,\n  p_credit_analytics jsonb   default '{}'::jsonb,\n  p_currency_id      bigint  default null,\n  p_currency_amount  numeric default null\n) returns bigint\nlanguage plpgsql\nas $$\ndeclare\n  v_entry_id bigint;\n  v_debit    record;\n  v_credit   record;\n  v_needs_currency  boolean;\n  v_needs_quantity  boolean;\n  v_currency_id     bigint;\n  v_currency_amount numeric;\n  v_quantity        numeric;\nbegin\n  if p_amount is null or p_amount = 0 then\n    raise exception 'Проводка % документа %: нульова сума', p_line_no, p_document_id;\n  end if;\n\n  select is_group, is_currency, is_quantitative into v_debit\n  from app.chart_of_account where code = p_debit_account;\n  if v_debit is null then\n    raise exception 'Рахунок дебету «%» не знайдено', p_debit_account;\n  elsif v_debit.is_group then\n    raise exception 'Рахунок дебету «%» — група, проводка неможлива', p_debit_account;\n  end if;\n\n  select is_group, is_currency, is_quantitative into v_credit\n  from app.chart_of_account where code = p_credit_account;\n  if v_credit is null then\n    raise exception 'Рахунок кредиту «%» не знайдено', p_credit_account;\n  elsif v_credit.is_group then\n    raise exception 'Рахунок кредиту «%» — група, проводка неможлива', p_credit_account;\n  end if;\n\n  v_needs_currency := v_debit.is_currency or v_credit.is_currency;\n  v_needs_quantity := v_debit.is_quantitative or v_credit.is_quantitative;\n\n  if v_needs_currency then\n    if p_currency_id is null or p_currency_amount is null then\n      raise exception 'Проводка %: валютний рахунок вимагає валюту й суму у валюті', p_line_no;\n    end if;\n    v_currency_id := p_currency_id;\n    v_currency_amount := p_currency_amount;\n  end if;  -- інакше лишаються null\n\n  if v_needs_quantity then\n    if p_quantity is null then\n      raise exception 'Проводка %: кількісний рахунок вимагає кількість', p_line_no;\n    end if;\n    v_quantity := p_quantity;\n  end if;\n\n  insert into app.journal_entry (\n    document_id, line_no, debit_account, credit_account, amount,\n    currency_id, currency_amount, quantity, description\n  )\n  values (\n    p_document_id, p_line_no, p_debit_account, p_credit_account, p_amount,\n    v_currency_id, v_currency_amount, v_quantity, p_description\n  )\n  returning id into v_entry_id;\n\n  perform app.doc_analytic_set(v_entry_id, 'debit',  p_debit_account,  p_debit_analytics);\n  perform app.doc_analytic_set(v_entry_id, 'credit', p_credit_account, p_credit_analytics);\n\n  return v_entry_id;\nend;\n$$;\n\n-- ── Завершення проведення ───────────────────────────────────────────────────\n\ndrop function if exists app.doc_post_finish(bigint, bigint);\ncreate function app.doc_post_finish(\n  p_user_id     bigint,\n  p_document_id bigint\n) returns void\nlanguage sql\nas $$\n  update app.document\n  set is_posted = true,\n      posted_at = now(),\n      posted_by = p_user_id,\n      updated_at = now(),\n      updated_by = p_user_id\n  where id = p_document_id;\n$$;\n\n-- ── Скасування проведення ───────────────────────────────────────────────────\n\ndrop function if exists app.doc_unpost(bigint, bigint);\ncreate function app.doc_unpost(\n  p_user_id     bigint,\n  p_document_id bigint\n) returns void\nlanguage sql\nas $$\n  with cleared as (\n    delete from app.journal_entry where document_id = p_document_id returning 1\n  )\n  update app.document\n  set is_posted = false,\n      posted_at = null,\n      posted_by = null,\n      updated_at = now(),\n      updated_by = p_user_id\n  where id = p_document_id;\n$$;\n",
  "document_core/db/migration.sql": "-- Міграції ядра документообігу.\n\n-- Валютний облік: колонки додаються до вже наповненого регістру, тому окремою\n-- міграцією, а не тільки в struc.sql (нові БД отримають їх звідти).\nalter table if exists app.journal_entry\n  add column if not exists currency_id bigint references app.currency (id);\nalter table if exists app.journal_entry\n  add column if not exists currency_amount numeric(18,2);\n",
  "document_core/db/struc.sql": "-- ═══════════════════════════════════════════════════════════════════════════\n-- Ядро документообігу та бухгалтерського регістру.\n--\n-- Ключове рішення: app.document — це ШАПКА, яка володіє ідентифікатором.\n-- Таблиця конкретного документа (app.invoice тощо) не має власної identity,\n-- її первинний ключ — document_id, що посилається на app.document. Звідси:\n--   • журнал документів = один запит до однієї таблиці, без UNION по типах;\n--   • посилання на документ = звичайний bigint, а не пара (тип, id);\n--   • проведення, нумерація, позначка на видалення живуть у ядрі один раз.\n--\n-- У шапці лише РЕАЛЬНО спільні реквізити. Контрагента, валюти, складу тут\n-- немає — вони спільні не для всіх документів. Для журналу натомість є\n-- денормалізовані total і presentation, які документ заповнює при записі.\n--\n-- Підсумків (залишків, оборотів) система не зберігає СВІДОМО: звіти рахують\n-- регістр повним скануванням за індексами нижче. Тому немає ні перерахунку\n-- при скасуванні проведення, ні розсинхрону підсумків із проводками.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── Типи документів ─────────────────────────────────────────────────────────\n-- Рядки генеруються з manifest.json моделей-документів при sql:assemble\n-- (див. _generated/document-types.data.sql), руками не наповнюються.\n\ncreate table if not exists app.document_type (\n  id         bigint generated by default as identity primary key,\n  code       varchar(50)  not null unique,   -- = ключ моделі з manifest.json\n  name       varchar(255) not null,\n  short_name varchar(50),                    -- колонка «Вид» у журналі та звітах\n  prefix     varchar(3),                     -- префікс автонумерації\n  sort_order int not null default 0\n);\n\n-- ── Шапка документа ─────────────────────────────────────────────────────────\n\ncreate table if not exists app.document (\n  id               bigint generated by default as identity primary key,\n  document_type_id bigint not null references app.document_type (id),\n  organization_id  bigint not null references app.organization (id),\n  number           varchar(20) not null,\n  -- Момент, а не дата: два документи одного дня мають детермінований порядок\n  -- проведення, інакше сальдо, що наростає, стрибає між запусками звіту.\n  doc_date         timestamp   not null,\n  -- Денормалізація заради журналу документів і списків посилань.\n  -- Заповнює документ при записі; джерело правди — його власні реквізити.\n  total            numeric(18,2) not null default 0,\n  presentation     text          not null default '',\n  description      text,\n  is_posted        boolean not null default false,\n  posted_at        timestamptz,\n  posted_by        bigint references app.users (id),\n  is_deleted       boolean not null default false,\n  created_at       timestamptz not null default now(),\n  created_by       bigint references app.users (id),\n  updated_at       timestamptz not null default now(),\n  updated_by       bigint references app.users (id)\n);\n\ncreate unique index if not exists uq_document_number\n  on app.document (document_type_id, organization_id, number);\n\n-- Журнал документів і відбір за періодом.\ncreate index if not exists ix_document_org_date\n  on app.document (organization_id, doc_date) where not is_deleted;\ncreate index if not exists ix_document_type_date\n  on app.document (document_type_id, doc_date desc) where not is_deleted;\n\n-- Основний вхід звітів: проведені документи організації за період.\ncreate index if not exists ix_document_posted\n  on app.document (organization_id, doc_date) where is_posted and not is_deleted;\n\ncreate index if not exists ix_document_number on app.document (number);\n\n-- ── Види аналітики (субконто) ───────────────────────────────────────────────\n-- Реєстр вимірів: що це за субконто і звідки SQL бере знімок представлення.\n-- Маршрут форми тут НЕ зберігається — клієнт резолвить його з view-manifest\n-- за model_key, щоб не дублювати той самий довідник у двох місцях.\n\ncreate table if not exists app.analytic_dimension (\n  code         varchar(100) primary key,\n  name         varchar(255) not null,\n  entity_kind  varchar(20)  not null check (entity_kind in ('catalog', 'document')),\n  model_key    varchar(100) not null,        -- ключ моделі для view-manifest\n  target_table varchar(255) not null,        -- звідки знімати code/name\n  id_column    varchar(100) not null default 'id',\n  code_column  varchar(100),\n  name_column  varchar(100),\n  is_active    boolean not null default true\n);\n\n-- ── Налаштування аналітики рахунку ──────────────────────────────────────────\n-- Які субконто і в яких слотах веде рахунок. Слотів три — як у типовому\n-- українському плані рахунків.\n\ncreate table if not exists app.chart_of_account_analytic (\n  id             bigint generated by default as identity primary key,\n  account_code   varchar(10)  not null references app.chart_of_account (code) on delete cascade,\n  slot_no        int          not null check (slot_no between 1 and 3),\n  dimension_code varchar(100) not null references app.analytic_dimension (code),\n  is_required    boolean not null default true,\n  constraint uq_chart_of_account_analytic_slot unique (account_code, slot_no)\n);\n\ncreate index if not exists ix_chart_of_account_analytic_account\n  on app.chart_of_account_analytic (account_code);\n\n-- ── Проводки ────────────────────────────────────────────────────────────────\n-- Кореспондентська модель: дебет і кредит в одному рядку.\n--\n-- amount — завжди у валюті обліку (гривні): саме по ній рахуються сальдо й\n-- обороти. Валютна сума (currency_amount у валюті currency_id) і кількість —\n-- додаткові виміри проводки, що вмикаються ознаками рахунку (is_currency,\n-- is_quantitative), як і субконто. Одна валютна сума й одна кількість на\n-- проводку: у кореспонденції валютним/кількісним є один бік із двох.\n\ncreate table if not exists app.journal_entry (\n  id              bigint generated by default as identity primary key,\n  document_id     bigint not null references app.document (id) on delete cascade,\n  line_no         int    not null,\n  debit_account   varchar(10) not null references app.chart_of_account (code),\n  credit_account  varchar(10) not null references app.chart_of_account (code),\n  amount          numeric(18,2) not null,\n  currency_id     bigint references app.currency (id),  -- валюта проводки\n  currency_amount numeric(18,2),                         -- сума у валюті\n  quantity        numeric(18,3),                         -- кількісний облік\n  description     text,\n  constraint uq_journal_entry_line unique (document_id, line_no)\n);\n\n-- Вхід звітів «картка рахунку» / «оборотно-сальдова»: відбір за рахунком,\n-- потім join до шапки за document_id. include(amount) робить обхід index-only.\ncreate index if not exists ix_journal_entry_debit\n  on app.journal_entry (debit_account, document_id) include (amount);\ncreate index if not exists ix_journal_entry_credit\n  on app.journal_entry (credit_account, document_id) include (amount);\ncreate index if not exists ix_journal_entry_document\n  on app.journal_entry (document_id);\n\n-- ── Значення аналітики проводки ─────────────────────────────────────────────\n-- Знімки коду й назви — щоб перейменування в довіднику не переписувало\n-- історію у звітах. value_id лишається живим посиланням для drill-down.\n\ncreate table if not exists app.journal_entry_analytic (\n  journal_entry_id   bigint not null references app.journal_entry (id) on delete cascade,\n  side               varchar(10)  not null check (side in ('debit', 'credit')),\n  slot_no            int          not null check (slot_no between 1 and 3),\n  dimension_code     varchar(100) not null references app.analytic_dimension (code),\n  value_id           bigint       not null,\n  value_code         varchar(100),\n  value_name         varchar(500),\n  value_presentation text         not null,\n  constraint pk_journal_entry_analytic primary key (journal_entry_id, side, slot_no)\n);\n\n-- Відбір звіту за конкретним субконто («обороти по контрагенту»).\ncreate index if not exists ix_journal_entry_analytic_value\n  on app.journal_entry_analytic (dimension_code, value_id);\n",
  "help_content/db/data.sql": "-- Intentionally empty. Seed or corrective data for help_content will be added here when needed.\n",
  "help_content/db/help_content.sql": "-- Intentionally empty. Re-runnable SQL functions for help_content will be added here when needed.\n",
  "help_content/db/migration.sql": "-- Intentionally empty. Structural migration steps for help_content will be added here when needed.\n",
  "help_content/db/struc.sql": "create table if not exists app.help_content (\n    id          bigint generated always as identity primary key,\n    model_key   text        not null,\n    field_key   text,\n    lang        char(2)     not null default 'uk',\n    content     text        not null,\n    kind        text        not null default 'tooltip',\n    updated_at  timestamptz not null default now(),\n    updated_by  text,\n\n    constraint uq_help_content unique (model_key, field_key, lang, kind)\n);\n\ncomment on table  app.help_content                is 'Контекстна довідка для екранів та полів';\ncomment on column app.help_content.model_key      is 'Ключ моделі з manifest.json, наприклад supplier_invoice';\ncomment on column app.help_content.field_key      is 'Ключ поля форми; null означає підказку для всього екрану';\ncomment on column app.help_content.lang           is 'Код мови (uk, en)';\ncomment on column app.help_content.content        is 'Текст підказки у форматі Markdown';\ncomment on column app.help_content.kind           is 'Місце відображення: tooltip | inline | chat';\ncomment on column app.help_content.updated_by     is 'Джерело запису: agent | admin';\n",
  "help_scenario/db/data.sql": "-- Intentionally empty. Seed or corrective data for help_scenario will be added here when needed.\n",
  "help_scenario/db/help_scenario.sql": "-- Intentionally empty. Re-runnable SQL functions for help_scenario will be added here when needed.\n",
  "help_scenario/db/migration.sql": "-- Intentionally empty. Structural migration steps for help_scenario will be added here when needed.\n",
  "help_scenario/db/struc.sql": "create table if not exists app.help_scenario (\n    id          bigint generated always as identity primary key,\n    slug        text        not null,\n    title       text        not null,\n    content     text        not null,\n    tags        text[]      not null default '{}',\n    lang        char(2)     not null default 'uk',\n    updated_at  timestamptz not null default now(),\n    updated_by  text,\n\n    constraint uq_help_scenario unique (slug, lang)\n);\n\ncreate index if not exists ix_help_scenario_tags on app.help_scenario using gin(tags);\n\ncomment on table  app.help_scenario             is 'Бізнес-процесні сценарії та інструкції для користувачів';\ncomment on column app.help_scenario.slug        is 'Унікальний технічний ідентифікатор сценарію, наприклад close-month';\ncomment on column app.help_scenario.title       is 'Назва сценарію, відображається у пошуку';\ncomment on column app.help_scenario.content     is 'Покроковий опис сценарію у форматі Markdown';\ncomment on column app.help_scenario.tags        is 'Теги для класифікації та фільтрації сценаріїв';\ncomment on column app.help_scenario.lang        is 'Код мови (uk, en)';\ncomment on column app.help_scenario.updated_by  is 'Джерело запису: agent | admin';\n",
  "menu/db/menu.sql": "-- Функції меню.\n--\n-- Дві групи: menu_current — завантаження меню поточного користувача (злиття +\n-- фільтр правами), решта — модельний контракт для адмін-екранів\n-- (list / get / save / delete / lookup) плюс copy.\n\n-- Прототип: A2v10-іменування (index/load/update) і функції інтерфейсів, чиї\n-- таблиці знято в struc.sql. Знімаються тут, бо в живій базі вони могли\n-- лишитися від ручної публікації і посилалися б на неіснуючі таблиці.\ndrop function if exists app.menu_index(bigint, jsonb);\ndrop function if exists app.menu_load(bigint, jsonb);\ndrop function if exists app.menu_update(bigint, jsonb);\ndrop function if exists app.menu_fetch(bigint, jsonb);\ndrop function if exists app.interface_index(bigint, jsonb);\ndrop function if exists app.interface_load(bigint, jsonb);\ndrop function if exists app.interface_update(bigint, jsonb);\ndrop function if exists app.interface_fetch(bigint, jsonb);\n\n/**\n * Меню поточного користувача: злиття меню всіх його активних груп, уже\n * відфільтроване правами.\n *\n * Чому фільтр саме тут, а не на клієнті: клієнт і так не відкриє пункт, на\n * який немає права, — але побачить його і сприйме відмову як поломку. Плюс\n * склад чужих екранів назовні не їде.\n *\n * Ідентичність пункту при злитті — ланцюжок `code` від кореня, а не id\n * (у різних меню вони різні) і не маршрут (у тек його немає). Цей самий шлях\n * іде назовні як `id`, тож клієнтові нема чого доклеювати.\n *\n * Порядок і переможець при дублі — мінімальний кортеж\n * (user_group_menu.sort_order, menu_item.sort_order). Той самий кортеж дає і\n * позицію, і те, чиї name/icon показати: інакше результат залежав би від плану\n * запиту.\n *\n * Повертає плоский список — дерево збирає клієнт за parentId.\n */\ndrop function if exists app.menu_current(bigint, jsonb);\ncreate function app.menu_current(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with recursive target as (\n    select user_id as uid\n  ),\n  assigned as (\n    select\n      mi.menu_id                                     as menu_id,\n      mi.id                                          as id,\n      mi.parent_id                                   as parent_id,\n      mi.code                                        as code,\n      mi.name                                        as name,\n      mi.icon_key                                    as icon_key,\n      nullif(btrim(coalesce(mi.route_path, '')), '') as route_path,\n      array[ugm.sort_order, mi.sort_order]           as sort_key\n    from app.user_group_member gm\n    join app.user_group g        on g.id = gm.user_group_id and g.is_active\n    join app.user_group_menu ugm on ugm.user_group_id = g.id and ugm.is_active\n    join app.menu mn             on mn.id = ugm.menu_id and mn.is_active\n    join app.menu_item mi        on mi.menu_id = mn.id and mi.is_active\n    cross join target t\n    where gm.user_id = t.uid and gm.is_active\n  ),\n  -- Жодна група користувача не має меню — беремо меню 'default'. Порожній\n  -- екран читається як поломка, а не як «вам нічого не призначили».\n  fallback as (\n    select\n      mi.menu_id, mi.id, mi.parent_id, mi.code, mi.name, mi.icon_key,\n      nullif(btrim(coalesce(mi.route_path, '')), ''),\n      array[0, mi.sort_order]\n    from app.menu mn\n    join app.menu_item mi on mi.menu_id = mn.id and mi.is_active\n    where mn.code = 'default'\n      and mn.is_active\n      and not exists (select 1 from assigned)\n  ),\n  source as (\n    select * from assigned\n    union all\n    select * from fallback\n  ),\n  tree as (\n    select\n      s.menu_id, s.id,\n      s.code::text as path,\n      null::text   as parent_path,\n      s.name, s.icon_key, s.route_path, s.sort_key\n    from source s\n    where s.parent_id is null\n\n    union all\n\n    select\n      s.menu_id, s.id,\n      p.path || '/' || s.code,\n      p.path,\n      s.name, s.icon_key, s.route_path, s.sort_key\n    from source s\n    join tree p on p.menu_id = s.menu_id and p.id = s.parent_id\n  ),\n  -- Модель — другий сегмент маршруту (`catalog/bank/list` → `bank`), тобто те\n  -- саме ім'я, що приходить у ModelRuntimeService.execute().\n  visible as (\n    select t.*\n    from tree t\n    cross join target tg\n    where t.route_path is null\n       or app.access_can(tg.uid, split_part(ltrim(t.route_path, '/'), '/', 2), 'view')\n  ),\n  -- Тека лишається, лише якщо під нею вцілів хоч один лист — на будь-якій\n  -- глибині. Порожня тека гірша за відсутню: у неї клікають.\n  kept as (\n    select v.*\n    from visible v\n    where v.route_path is not null\n       or exists (\n         select 1\n         from visible leaf\n         where leaf.route_path is not null\n           and starts_with(leaf.path, v.path || '/')\n       )\n  ),\n  merged as (\n    select distinct on (k.path)\n      k.path, k.parent_path, k.name, k.icon_key, k.route_path, k.sort_key\n    from kept k\n    order by k.path, k.sort_key, k.name\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((\n        select jsonb_agg(\n          jsonb_build_object(\n            'id',       m.path,\n            'parentId', m.parent_path,\n            'name',     m.name,\n            'icon',     m.icon_key,\n            'route',    m.route_path\n          )\n          order by m.sort_key, m.path\n        )\n        from merged m\n      ), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', jsonb_build_object('count', (select count(*) from merged))\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\n-- ── Адміністрування меню ───────────────────────────────────────────────────\n\n/** Порожня частина `data` конверта — щоб відповіді-помилки мали ту саму форму. */\ndrop function if exists app.menu_empty_data();\ncreate function app.menu_empty_data()\nreturns jsonb\nlanguage sql\nimmutable\nas $$\n  select jsonb_build_object('item', null, 'rows', '[]'::jsonb, 'options', '{}'::jsonb, 'totals', '{}'::jsonb);\n$$;\n\ndrop function if exists app.menu_fail(text);\ncreate function app.menu_fail(p_message text)\nreturns jsonb\nlanguage sql\nimmutable\nas $$\n  select jsonb_build_object('ok', false, 'data', app.menu_empty_data(), 'messages', jsonb_build_array(p_message));\n$$;\n\ndrop function if exists app.menu_list(bigint, jsonb);\ncreate function app.menu_list(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '')                                   as search,\n      greatest(coalesce((payload->>'page')::int, 1), 1)                  as page,\n      least(greatest(coalesce((payload->>'pageSize')::int, 20), 1), 200) as page_size,\n      coalesce(nullif(payload->>'sortBy', ''), 'code')                   as sort_by,\n      case lower(coalesce(payload->>'sortDir', 'asc')) when 'desc' then 'desc' else 'asc' end as sort_dir\n  ),\n  filtered as (\n    select\n      m.id::text                                              as id,\n      m.code                                                  as code,\n      m.name                                                  as name,\n      m.is_active                                             as \"isActive\",\n      count(distinct mi.id) filter (where mi.is_active)::int   as \"itemCount\",\n      count(distinct ugm.id) filter (where ugm.is_active)::int as \"groupCount\"\n    from app.menu m\n    left join app.menu_item mi        on mi.menu_id = m.id\n    left join app.user_group_menu ugm on ugm.menu_id = m.id\n    cross join params p\n    where p.search = ''\n       or m.code ilike '%' || p.search || '%'\n       or m.name ilike '%' || p.search || '%'\n    group by m.id, m.code, m.name, m.is_active\n  ),\n  paged as (\n    select f.* from filtered f cross join params p\n    order by\n      case when p.sort_by = 'code'       and p.sort_dir = 'asc'  then f.code end asc,\n      case when p.sort_by = 'code'       and p.sort_dir = 'desc' then f.code end desc,\n      case when p.sort_by = 'name'       and p.sort_dir = 'asc'  then f.name end asc,\n      case when p.sort_by = 'name'       and p.sort_dir = 'desc' then f.name end desc,\n      case when p.sort_by = 'itemCount'  and p.sort_dir = 'asc'  then f.\"itemCount\" end asc,\n      case when p.sort_by = 'itemCount'  and p.sort_dir = 'desc' then f.\"itemCount\" end desc,\n      case when p.sort_by = 'groupCount' and p.sort_dir = 'asc'  then f.\"groupCount\" end asc,\n      case when p.sort_by = 'groupCount' and p.sort_dir = 'desc' then f.\"groupCount\" end desc,\n      f.code asc\n    limit (select page_size from params)\n    offset ((select page from params) - 1) * (select page_size from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(paged)) from paged), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', jsonb_build_object(\n        'count', (select count(*) from filtered),\n        'page', (select page from params),\n        'pageSize', (select page_size from params)\n      )\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\n/**\n * Меню з пунктами й призначеними групами.\n *\n * Пункти йдуть у порядку дерева (шлях із code), а не за id: у формі це плоска\n * таблиця, і без такого порядку діти опиняються далеко від батьків.\n */\ndrop function if exists app.menu_get(bigint, jsonb);\ncreate function app.menu_get(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with recursive target as (\n    select nullif(payload->>'id', '')::bigint as id\n  ),\n  found as (\n    select m.* from app.menu m cross join target t where m.id = t.id\n  ),\n  -- `sort_path` — ключ обходу дерева: на кожному рівні спершу sort_order, потім\n  -- code як розв'язувач нічиїх. Зсув на 2^31 робить число завжди додатним, бо\n  -- порівнюються рядки: без нього «-20» опинилося б не там, де −20.\n  tree as (\n    select\n      mi.*, mi.code::text as path, null::varchar(100) as parent_code,\n      array[lpad((mi.sort_order::bigint + 2147483648)::text, 11, '0') || ':' || mi.code] as sort_path\n    from app.menu_item mi cross join target t\n    where mi.menu_id = t.id and mi.parent_id is null\n\n    union all\n\n    select\n      mi.*, p.path || '/' || mi.code, p.code,\n      p.sort_path || (lpad((mi.sort_order::bigint + 2147483648)::text, 11, '0') || ':' || mi.code)\n    from app.menu_item mi\n    join tree p on p.menu_id = mi.menu_id and p.id = mi.parent_id\n  ),\n  entries as (\n    select\n      t.id::text    as id,\n      t.parent_code as \"parentCode\",\n      t.code        as code,\n      t.name        as name,\n      t.icon_key    as \"iconKey\",\n      t.route_path  as \"routePath\",\n      t.sort_order  as \"sortOrder\",\n      t.is_active   as \"isActive\"\n    from tree t\n    order by t.sort_path\n  ),\n  assigned as (\n    select g.id::text as id\n    from app.user_group_menu ugm\n    join app.user_group g on g.id = ugm.user_group_id\n    cross join target t\n    where ugm.menu_id = t.id and ugm.is_active\n    order by g.code\n  ),\n  all_groups as (\n    select g.id::text as id, g.name from app.user_group g where g.is_active order by g.code\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', (\n        select jsonb_build_object(\n          'id', f.id::text,\n          'code', f.code,\n          'name', f.name,\n          'isActive', f.is_active,\n          'groupIds', coalesce((select jsonb_agg(id) from assigned), '[]'::jsonb),\n          'entries', coalesce((select jsonb_agg(row_to_json(entries)) from entries), '[]'::jsonb)\n        )\n        from found f\n      ),\n      'rows', '[]'::jsonb,\n      'options', jsonb_build_object(\n        'groups', coalesce((select jsonb_agg(row_to_json(all_groups)) from all_groups), '[]'::jsonb)\n      ),\n      'totals', '{}'::jsonb\n    ),\n    'messages', case when exists (select 1 from found)\n      then '[]'::jsonb\n      else jsonb_build_array('Меню не знайдено') end\n  );\n$$;\n\n/**\n * Запис меню разом із пунктами й призначенням групам.\n * payload = { item: { id, code, name, isActive, groupIds[], entries[] } }\n * `entries` і `groupIds` — повний стан, а не дельта.\n *\n * Батько пункту задається `parentCode`, тому код унікальний у межах меню\n * (індекс у БД дозволяє більше — однакові коди під різними батьками, — але\n * форма цим не користується, а прив'язка за кодом вимагає однозначності).\n *\n * Усі перевірки — ДО першого запису. Функція виконується в одній транзакції з\n * викликом, тож вихід із конвертом-помилкою після часткового запису цей запис\n * би зафіксував; єдиний спосіб відкотити — raise, а це вже не конверт.\n */\ndrop function if exists app.menu_save(bigint, jsonb);\ncreate function app.menu_save(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_item    jsonb    := coalesce(payload->'item', '{}'::jsonb);\n  v_id      bigint   := nullif(v_item->>'id', '')::bigint;\n  v_code    text     := trim(coalesce(v_item->>'code', ''));\n  v_name    text     := trim(coalesce(v_item->>'name', ''));\n  v_active  boolean  := coalesce((v_item->>'isActive')::boolean, true);\n  v_entries jsonb    := coalesce(v_item->'entries', '[]'::jsonb);\n  v_groups  bigint[] := coalesce(\n    (select array_agg(value::bigint) from jsonb_array_elements_text(coalesce(v_item->'groupIds', '[]'::jsonb))),\n    '{}'::bigint[]\n  );\n  v_total   int := jsonb_array_length(v_entries);\n  v_reached int;\n  v_added   int;\n  v_bad     text;\nbegin\n  if v_code = '' then\n    return app.menu_fail('Код меню обов''язковий');\n  end if;\n\n  if v_name = '' then\n    return app.menu_fail('Назва меню обов''язкова');\n  end if;\n\n  if exists (select 1 from app.menu m where lower(m.code) = lower(v_code) and (v_id is null or m.id <> v_id)) then\n    return app.menu_fail('Меню з таким кодом уже є');\n  end if;\n\n  -- Розгорнутий payload пунктів. Тимчасова таблиця, а не повторення\n  -- jsonb_array_elements у кожному операторі: перевірок над ним чотири.\n  drop table if exists _menu_entries;\n  create temp table _menu_entries on commit drop as\n  select\n    nullif(trim(coalesce(je->>'parentCode', '')), '') as parent_code,\n    trim(coalesce(je->>'code', ''))                   as code,\n    trim(coalesce(je->>'name', ''))                   as name,\n    nullif(trim(coalesce(je->>'iconKey', '')), '')    as icon_key,\n    nullif(trim(coalesce(je->>'routePath', '')), '')  as route_path,\n    coalesce((je->>'sortOrder')::int, 0)              as sort_order,\n    coalesce((je->>'isActive')::boolean, true)        as is_active\n  from jsonb_array_elements(v_entries) as je;\n\n  if exists (select 1 from _menu_entries where code = '') then\n    return app.menu_fail('Код пункту обов''язковий');\n  end if;\n\n  if exists (select 1 from _menu_entries where name = '') then\n    return app.menu_fail('Назва пункту обов''язкова');\n  end if;\n\n  select e.code into v_bad from _menu_entries e group by e.code having count(*) > 1 limit 1;\n  if v_bad is not null then\n    return app.menu_fail(format('Код пункту «%s» повторюється — коди мають бути унікальними в межах меню', v_bad));\n  end if;\n\n  select e.parent_code into v_bad\n  from _menu_entries e\n  where e.parent_code is not null\n    and not exists (select 1 from _menu_entries p where p.code = e.parent_code)\n  limit 1;\n  if v_bad is not null then\n    return app.menu_fail(format('Невідомий батьківський код «%s»', v_bad));\n  end if;\n\n  -- Обхід від коренів має покрити всі пункти. Не покрив — десь цикл.\n  with recursive reach as (\n    select e.code from _menu_entries e where e.parent_code is null\n    union all\n    select e.code from _menu_entries e join reach r on e.parent_code = r.code\n  )\n  select count(*) into v_reached from reach;\n\n  if v_reached <> v_total then\n    return app.menu_fail('Циклічна прив''язка пунктів: частина з них недосяжна від кореня');\n  end if;\n\n  if v_id is null then\n    insert into app.menu (code, name, is_active) values (v_code, v_name, v_active) returning id into v_id;\n  else\n    update app.menu set code = v_code, name = v_name, is_active = v_active, updated_at = now() where id = v_id;\n    if not found then\n      return app.menu_fail('Меню не знайдено');\n    end if;\n  end if;\n\n  -- Пункти переписуються цілком. На menu_item не посилається ніщо, крім нього\n  -- самого (складений FK на батька), а зовні пункт адресується шляхом із code,\n  -- не id, — тож перестворення нічого не рве.\n  delete from app.menu_item where menu_id = v_id;\n\n  -- Вставка хвилями: спершу корені, далі ті, чий батько вже вставлений.\n  -- Ациклічність уже перевірено, тож цикл завершується, покривши всі пункти.\n  loop\n    insert into app.menu_item (menu_id, parent_id, code, name, icon_key, route_path, sort_order, is_active)\n    select v_id, p.id, e.code, e.name, e.icon_key, e.route_path, e.sort_order, e.is_active\n    from _menu_entries e\n    left join app.menu_item p on p.menu_id = v_id and p.code = e.parent_code\n    where not exists (select 1 from app.menu_item x where x.menu_id = v_id and x.code = e.code)\n      and (e.parent_code is null or p.id is not null);\n\n    get diagnostics v_added = row_count;\n    exit when v_added = 0;\n  end loop;\n\n  -- Призначення групам — теж повний стан.\n  delete from app.user_group_menu ugm where ugm.menu_id = v_id and not (ugm.user_group_id = any(v_groups));\n\n  insert into app.user_group_menu (user_group_id, menu_id, is_active)\n  select g, v_id, true from unnest(v_groups) as g\n  on conflict (user_group_id, menu_id) do update set is_active = true, updated_at = now();\n\n  return app.menu_get(user_id, jsonb_build_object('id', v_id::text));\nend;\n$$;\n\ndrop function if exists app.menu_delete(bigint, jsonb);\ncreate function app.menu_delete(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_id bigint := nullif(payload->>'id', '')::bigint;\nbegin\n  if v_id is null then\n    return app.menu_fail('id обов''язковий');\n  end if;\n\n  -- Пункти й призначення групам зникають каскадом: посилатися на меню ззовні\n  -- нема кому, історії воно не несе.\n  delete from app.menu where id = v_id;\n  if not found then\n    return app.menu_fail('Меню не знайдено');\n  end if;\n\n  return jsonb_build_object('ok', true, 'data', app.menu_empty_data(), 'messages', '[]'::jsonb);\nend;\n$$;\n\ndrop function if exists app.menu_lookup(bigint, jsonb);\ncreate function app.menu_lookup(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  with params as (\n    select\n      coalesce(payload->>'search', '') as search,\n      least(coalesce((payload->>'limit')::int, 50), 200) as lim\n  ),\n  found as (\n    select m.id::text as id, m.name\n    from app.menu m\n    cross join params p\n    where m.is_active\n      and (p.search = '' or m.code ilike '%' || p.search || '%' or m.name ilike '%' || p.search || '%')\n    order by m.code\n    limit (select lim from params)\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', null,\n      'rows', coalesce((select jsonb_agg(row_to_json(found)) from found), '[]'::jsonb),\n      'options', '{}'::jsonb,\n      'totals', '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb\n  );\n$$;\n\n/**\n * Копія меню разом з усіма пунктами. payload = { id }.\n *\n * Призначення групам НЕ копіюються свідомо. Меню всіх груп користувача\n * зливаються, тож копія в тих самих групах не дала б нічого нового — злилася б\n * із оригіналом назад у той самий список. Копію призначають уже після правки.\n *\n * Дерево переноситься хвилями (корені → діти вже скопійованих), а прив'язка\n * батька шукається за кодом: id у копії інші. Тому коди в межах меню мусять\n * бути унікальні — це перевіряється до першого запису.\n */\ndrop function if exists app.menu_copy(bigint, jsonb);\ncreate function app.menu_copy(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_id    bigint := nullif(payload->>'id', '')::bigint;\n  v_src   app.menu%rowtype;\n  v_new   bigint;\n  v_code  text;\n  v_n     int := 1;\n  v_added int;\nbegin\n  if v_id is null then\n    return app.menu_fail('id обов''язковий');\n  end if;\n\n  select * into v_src from app.menu where id = v_id;\n  if not found then\n    return app.menu_fail('Меню не знайдено');\n  end if;\n\n  if exists (\n    select 1 from app.menu_item where menu_id = v_id group by code having count(*) > 1\n  ) then\n    return app.menu_fail('У меню є пункти з однаковим кодом — копіювання потребує унікальних');\n  end if;\n\n  -- Вільний код: `_copy`, далі `_copy2`, `_copy3`… Обрізання до 90/88 символів\n  -- лишає місце під суфікс — колонка має ліміт 100.\n  v_code := left(v_src.code, 90) || '_copy';\n  while exists (select 1 from app.menu m where lower(m.code) = lower(v_code)) loop\n    v_n := v_n + 1;\n    v_code := left(v_src.code, 88) || '_copy' || v_n;\n  end loop;\n\n  insert into app.menu (code, name, is_active)\n  values (v_code, left(v_src.name || ' (копія)', 255), v_src.is_active)\n  returning id into v_new;\n\n  loop\n    insert into app.menu_item (menu_id, parent_id, code, name, icon_key, route_path, sort_order, is_active)\n    select v_new, np.id, s.code, s.name, s.icon_key, s.route_path, s.sort_order, s.is_active\n    from app.menu_item s\n    left join app.menu_item sp on sp.id = s.parent_id                       -- батько в оригіналі\n    left join app.menu_item np on np.menu_id = v_new and np.code = sp.code  -- його копія\n    where s.menu_id = v_id\n      and not exists (select 1 from app.menu_item x where x.menu_id = v_new and x.code = s.code)\n      and (s.parent_id is null or np.id is not null);\n\n    get diagnostics v_added = row_count;\n    exit when v_added = 0;\n  end loop;\n\n  return app.menu_get(user_id, jsonb_build_object('id', v_new::text));\nend;\n$$;\n",
  "menu/db/struc.sql": "-- Меню: склад навігації, і тільки він.\n--\n-- Структура й функції — у ядрі: оболонка без навігації не працює, а\n-- app.user_group_menu посилається на app.user_group з пакета access. Сам СКЛАД\n-- пунктів — ні: маршрути належать конкретному застосунку, тож сід лишається в\n-- нього (app/admin/menu/db/data.sql), як і екрани редагування меню.\n--\n-- Прав тут немає жодного поля — вони живуть у app.user_group_permission і\n-- лишаються єдиним джерелом. Пункт показується, коли він є в меню групи\n-- І користувач має право `view` на модель його маршруту (див. app.menu_current).\n-- Два джерела правди про доступ розійшлися б, і розійшлися б тихо.\n--\n-- Рівень «інтерфейс» (група → інтерфейс → меню) знято свідомо: він не додавав\n-- жодного випадку, невиразного без нього — «дати групі меню A і B» однаково\n-- описується і двома інтерфейсами, і одним інтерфейсом із двома меню, і прямим\n-- зв'язком групи з меню. Лишився прямий зв'язок.\n\ncreate schema if not exists app;\n\n-- ── Одноразове прибирання прототипу ────────────────────────────────────────\n-- Таблиці меню/інтерфейсів існували в базі від попереднього прототипу, але їх\n-- не створював жоден підключений скрипт (моделі не було в sql.json), тож\n-- форма їх непередбачувана — під маркер годиться лише щось із НОВОЇ схеми.\n-- app.user_group_menu не існує рівно до першої публікації цього файлу, тому\n-- умова істинна один-єдиний раз. Без неї кожна публікація зносила б\n-- відредаговане адміністратором меню.\ndo $$\nbegin\n  if to_regclass('app.user_group_menu') is null then\n    drop table if exists app.menu_item cascade;\n    drop table if exists app.menu cascade;\n  end if;\nend $$;\n\n-- Інтерфейси більше не створюються ніде, тож знімаються безумовно.\n-- app.user_interface / app.user_group_interface зносить ядро (@core/access).\ndrop table if exists app.interface_menu cascade;\ndrop table if exists app.interface cascade;\n\n-- ── Меню ───────────────────────────────────────────────────────────────────\n-- Іменований набір пунктів. Це і є одиниця, яку адміністратор редагує та\n-- перевикористовує між групами: меню з назвою «Інтерфейс бухгалтера» — рівно\n-- те саме, чим був би окремий запис у таблиці інтерфейсів.\ncreate table if not exists app.menu (\n  id         bigint generated by default as identity primary key,\n  code       varchar(100) not null unique,\n  name       varchar(255) not null,\n  is_active  boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate index if not exists ix_menu_is_active on app.menu (is_active);\n\ncreate table if not exists app.menu_item (\n  id         bigint generated by default as identity primary key,\n  menu_id    bigint not null references app.menu (id) on delete cascade,\n  parent_id  bigint,\n  -- Ключ злиття, а не просто мнемоніка. Пункти з різних меню вважаються одним\n  -- і тим самим, коли збігається ланцюжок code від кореня: тека «Довідники» з\n  -- двох меню зіллється в одну, якщо в обох у неї code = 'catalog'.\n  code       varchar(100) not null,\n  name       varchar(255) not null,\n  icon_key   varchar(100),\n  -- Маршрут в'ю (`family/model/view`), як у tab.open. null → тека.\n  route_path varchar(500),\n  sort_order int not null default 0,\n  is_active  boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint uq_menu_item_menu_id_id unique (menu_id, id),\n  -- Складений FK гарантує, що батько — з того самого меню. Без нього дерево\n  -- може перетнути межу меню, і це не видно ні звідки.\n  constraint fk_menu_item_parent\n    foreign key (menu_id, parent_id) references app.menu_item (menu_id, id) on delete cascade,\n  constraint ck_menu_item_not_self_parent check (parent_id is null or parent_id <> id)\n);\n\n-- nulls not distinct (PG 15+) — інакше унікальність не діяла б на коренях,\n-- де parent_id is null, а це саме той рівень, де дублікати найпомітніші.\ncreate unique index if not exists uq_menu_item_code\n  on app.menu_item (menu_id, parent_id, code) nulls not distinct;\n\ncreate index if not exists ix_menu_item_tree\n  on app.menu_item (menu_id, parent_id, sort_order, id) where is_active;\n\n-- ── Призначення групі ──────────────────────────────────────────────────────\n-- Кілька меню на групу і кілька груп на користувача — злиття при завантаженні\n-- неминуче в будь-якому разі, тож M:N нічого не ускладнює.\n--\n-- Зв'язок лежить тут, а не колонкою в app.user_group, свідомо: колонка змусила б\n-- пакет access посилатися на app.menu, тобто залежати від підсистеми меню.\n-- Так залежність односпрямована — menu знає про access, access про menu ні,\n-- і застосунок може підключити access без меню.\ncreate table if not exists app.user_group_menu (\n  id            bigint generated by default as identity primary key,\n  user_group_id bigint not null references app.user_group (id) on delete cascade,\n  menu_id       bigint not null references app.menu (id) on delete cascade,\n  sort_order    int not null default 0,\n  is_active     boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\ncreate unique index if not exists uq_user_group_menu\n  on app.user_group_menu (user_group_id, menu_id);\n\ncreate index if not exists ix_user_group_menu_menu\n  on app.user_group_menu (menu_id) where is_active;\n",
  "print_template/db/data.sql": "-- Print templates declared in model manifests are published by scripts/assemble-sql-package.ts.",
  "print_template/db/migration.sql": "-- Міграцій ще немає: app.print_template створюється struc.sql із нуля.\n",
  "print_template/db/print_template.sql": "-- Ядро підсистеми друку: підбір активного шаблону для моделі.\n--\n-- Єдина SQL-функція, потрібна рантайму друку. Її викликає хендлер\n-- runtime.printPdf (server/modules/print). CRUD шаблонів живе в\n-- admin-моделі app/admin/print_template.\n\n-- Підбір активного шаблону для моделі: явно вказаний код, інакше — шаблон за\n-- замовчуванням, інакше — найсвіжіший активний. Викликає TS-команда printPdf.\ndrop function if exists app.print_template_resolve(bigint, jsonb);\ncreate function app.print_template_resolve(user_id bigint, payload jsonb)\nreturns jsonb\nlanguage sql\nas $$\n  select jsonb_build_object(\n    'ok', true,\n    'data', jsonb_build_object(\n      'item', (\n        select jsonb_build_object(\n          'id',          t.id::text,\n          'code',        t.code,\n          'name',        t.name,\n          'targetModel', t.target_model,\n          'dataCommand', t.data_command,\n          'paperSize',   t.paper_size,\n          'orientation', t.orientation,\n          'isDefault',   t.is_default,\n          'isActive',    t.is_active,\n          'schema',      t.template_schema\n        )\n        from app.print_template t\n        where t.target_model = nullif(trim(coalesce(payload->>'targetModel', '')), '')\n          and t.is_active\n          and (\n            nullif(trim(coalesce(payload->>'templateCode', '')), '') is null\n            or t.code = nullif(trim(coalesce(payload->>'templateCode', '')), '')\n          )\n        order by t.is_default desc, t.updated_at desc, t.code asc\n        limit 1\n      ),\n      'rows',    '[]'::jsonb,\n      'options', '{}'::jsonb,\n      'totals',  '{}'::jsonb,\n      'extra',   '{}'::jsonb\n    ),\n    'messages', '[]'::jsonb,\n    'meta', '{}'::jsonb\n  );\n$$;\n",
  "print_template/db/struc.sql": "create table if not exists app.print_template (\n  id              bigint generated by default as identity primary key,\n  code            varchar(80)  not null,\n  name            varchar(250) not null,\n  target_model    varchar(80)  not null,\n  data_command    varchar(80)  not null default 'get',\n  paper_size      varchar(20)  not null default 'A4',\n  orientation     varchar(20)  not null default 'portrait',\n  is_default      boolean      not null default false,\n  is_active       boolean      not null default true,\n  template_schema jsonb        not null default '{}'::jsonb,\n  created_at      timestamptz  not null default now(),\n  updated_at      timestamptz  not null default now(),\n  constraint print_template_paper_size_check  check (paper_size in ('A4')),\n  constraint print_template_orientation_check check (orientation in ('portrait', 'landscape'))\n);\n\ncreate unique index if not exists uq_print_template_code on app.print_template (code);\n\n-- Не більше одного шаблону за замовчуванням на модель.\ncreate unique index if not exists uq_print_template_default_per_model\n  on app.print_template (target_model)\n  where is_default;\n\ncreate index if not exists ix_print_template_target_model on app.print_template (target_model);\ncreate index if not exists ix_print_template_is_active    on app.print_template (is_active);\n",
};
